functions.fail_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.fail_v1(p_attempt uuid, p_token text, p_error text, p_retry boolean, p_delay integer, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare jid text;j population_top3000_202608_202609_v1.acquisition_job%rowtype;reserved bigint;n integer;retry boolean;
begin
-- Completed jobs cannot be overwritten by uncertain ACK/HTTP outcomes.
if exists(select 1 from population_top3000_202608_202609_v1.acquisition_attempt attempt_row join population_top3000_202608_202609_v1.acquisition_job job_row on job_row.job_id=attempt_row.job_id where attempt_row.attempt_id=p_attempt and attempt_row.token_sha256=encode(sha256(convert_to(p_token,'UTF8')),'hex') and job_row.status='COMPLETE') then return '{"state":"ALREADY_COMMITTED"}';end if;
jid:=population_top3000_202608_202609_v1.assert_attempt_v1(p_attempt,p_token);
select * into j from population_top3000_202608_202609_v1.acquisition_job where job_id=jid;
n:=case when j.last_error=p_error then j.consecutive_error_count+1 else 1 end;
retry:=p_retry and n<2 and j.attempts<j.max_attempts;
select reserved_bytes into reserved from population_top3000_202608_202609_v1.acquisition_attempt where attempt_id=p_attempt;
update population_top3000_202608_202609_v1.acquisition_control set reserved_bytes=greatest(0,reserved_bytes-reserved),hold_reason=case when p_error in('PROVIDER_HTTP_401','PROVIDER_HTTP_403','PROVIDER_CREDENTIAL_MISSING','DATABASE_AUTHENTICATION','DATABASE_PERMISSION') then p_error else hold_reason end,updated_at=clock_timestamp() where singleton;
if p_error='PROVIDER_HTTP_429' then update population_top3000_202608_202609_v1.acquisition_control set next_provider_at=greatest(next_provider_at,clock_timestamp()+make_interval(secs=>greatest(1,p_delay))) where singleton;end if;
update population_top3000_202608_202609_v1.acquisition_attempt set reserved_bytes=0,status='FAILED',result=jsonb_build_object('error',p_error,'retry',retry,'evidence',p_evidence) where attempt_id=p_attempt;
update population_top3000_202608_202609_v1.acquisition_job set status=case when retry then 'READY' else 'BLOCKED' end,last_error=p_error,consecutive_error_count=n,not_before=clock_timestamp()+make_interval(secs=>greatest(1,p_delay)),lease_until=null,updated_at=clock_timestamp() where job_id=jid;
insert into population_top3000_202608_202609_v1.acquisition_event(job_id,attempt_id,event,details)values(jid,p_attempt,'FAILED',jsonb_build_object('error',p_error,'retry',retry,'same_error_count',n,'evidence',p_evidence));
return jsonb_build_object('state',case when retry then 'RETRY_SCHEDULED' else 'BLOCKED' end,'error',p_error);
end $function$

functions.claim_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.claim_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare jid text;j population_top3000_202608_202609_v1.acquisition_job%rowtype;c population_top3000_202608_202609_v1.acquisition_control%rowtype;cached boolean;
begin
jid:=population_top3000_202608_202609_v1.assert_attempt_v1(p_attempt,p_token);
if exists(select 1 from population_top3000_202608_202609_v1.acquisition_attempt where attempt_id=p_attempt and claimed_at is not null) then return '{"state":"REPLAY_REJECTED"}';end if;
select * into c from population_top3000_202608_202609_v1.acquisition_control where singleton;
cached:=exists(select 1 from population_top3000_202608_202609_v1.acquisition_raw where job_id=jid);
if not cached then
 if c.next_provider_at>clock_timestamp() then return jsonb_build_object('state','RATE_WAIT','milliseconds',greatest(1,ceil(extract(epoch from(c.next_provider_at-clock_timestamp()))*1000)));end if;
 if c.provider_requests>=c.max_provider_requests or c.stored_bytes+c.reserved_bytes+8388608>c.max_source_bytes then
  update population_top3000_202608_202609_v1.acquisition_control set hold_reason='REQUEST_OR_BYTES_ADMISSION_EXHAUSTED',updated_at=clock_timestamp() where singleton;
  return '{"state":"BUDGET_HOLD"}';
 end if;
 update population_top3000_202608_202609_v1.acquisition_control set provider_requests=provider_requests+1,reserved_bytes=reserved_bytes+8388608,next_provider_at=clock_timestamp()+interval '500 milliseconds' where singleton;
end if;
update population_top3000_202608_202609_v1.acquisition_attempt set claimed_at=clock_timestamp(),provider_started_at=case when cached then null else clock_timestamp() end,reserved_bytes=case when cached then 0 else 8388608 end,status='CLAIMED' where attempt_id=p_attempt;
select * into j from population_top3000_202608_202609_v1.acquisition_job where job_id=jid;
return jsonb_build_object('state','CLAIMED','cached',cached,'job',jsonb_build_object('job_id',j.job_id,'kind',j.kind,'snapshot_date',j.snapshot_date,'ticker',j.ticker,'params',j.params,'page_number',j.page_number),'scope_sha256',c.scope_sha256);
end $function$

functions.finish_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.finish_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare jid text;j population_top3000_202608_202609_v1.acquisition_job%rowtype;d jsonb;e jsonb;cursor_value text;rows_count integer;enqueued integer:=0;v_result jsonb;
begin
if exists(select 1 from population_top3000_202608_202609_v1.acquisition_attempt attempt_row join population_top3000_202608_202609_v1.acquisition_job job_row on job_row.job_id=attempt_row.job_id where attempt_row.attempt_id=p_attempt and attempt_row.token_sha256=encode(sha256(convert_to(p_token,'UTF8')),'hex') and job_row.status='COMPLETE') then return '{"state":"ALREADY_COMMITTED"}';end if;
jid:=population_top3000_202608_202609_v1.assert_attempt_v1(p_attempt,p_token);
select * into j from population_top3000_202608_202609_v1.acquisition_job where job_id=jid;
select raw_text::jsonb,evidence into d,e from population_top3000_202608_202609_v1.acquisition_raw where job_id=jid;
if not found then raise exception 'SOURCE_NOT_PERSISTED';end if;
if coalesce(d->>'status','') not in('OK','DELAYED') then raise exception 'SOURCE_STATUS_INVALID';end if;
if j.kind='CENSUS' then
 if jsonb_typeof(d->'results') is distinct from 'array' then raise exception 'CENSUS_PAGE_INVALID';end if;
 if jsonb_array_length(d->'results')>1000 or jsonb_array_length(d->'results')=0 then raise exception 'CENSUS_PAGE_INVALID';end if;
 rows_count:=jsonb_array_length(d->'results');
 if exists(select 1 from jsonb_array_elements(d->'results') r where nullif(r->>'ticker','') is null or r->>'market' is distinct from 'stocks' or r->>'locale' is distinct from 'us' or r->>'active' is distinct from 'true') then raise exception 'CENSUS_SCOPE_MISMATCH';end if;
 insert into population_top3000_202608_202609_v1.reference_row(page_job_id,ordinal,ticker,security_type,raw_record)
 select jid,ord::integer,r->>'ticker',r->>'type',r from jsonb_array_elements(d->'results') with ordinality q(r,ord) on conflict do nothing;
 cursor_value:=nullif(e->>'next_cursor','');
 if cursor_value is not null then
  if cursor_value=j.params->>'cursor' or exists(select 1 from population_top3000_202608_202609_v1.acquisition_job where kind='CENSUS' and params->>'cursor'=cursor_value) then raise exception 'PAGINATION_CURSOR_REPEATED';end if;
  insert into population_top3000_202608_202609_v1.acquisition_job(job_id,kind,snapshot_date,page_number,params)
  values('census:2026-08-03:'||lpad((j.page_number+1)::text,6,'0'),'CENSUS',j.snapshot_date,j.page_number+1,jsonb_build_object('cursor',cursor_value));
  enqueued:=1;
 else
  if d ? 'next_url' and nullif(d->>'next_url','') is not null then raise exception 'PAGINATION_EVIDENCE_MISSING';end if;
  insert into population_top3000_202608_202609_v1.acquisition_job(job_id,kind,snapshot_date,ticker,params)
  select 'overview:2026-08-03:'||ticker,'OVERVIEW','2026-08-03',ticker,'{"date":"2026-08-03"}'::jsonb
  from population_top3000_202608_202609_v1.reference_row where security_type in('CS','ADRC','OS','NYRS','GDR','OTHER') or security_type is null group by ticker on conflict do nothing;
  get diagnostics enqueued=row_count;
  update population_top3000_202608_202609_v1.acquisition_control set next_stage='OVERVIEW_ACQUISITION',next_action='Acquire dated ticker overviews for every potentially eligible or unclassified census row; company membership remains unresolved.' where singleton;
 end if;
else
 if jsonb_typeof(d->'results') is distinct from 'object' or d#>>'{results,ticker}' is distinct from j.ticker then raise exception 'OVERVIEW_IDENTITY_MISMATCH';end if;
 insert into population_top3000_202608_202609_v1.ticker_overview(ticker,snapshot_date,source_job_id,raw_record) values(j.ticker,j.snapshot_date,jid,d->'results') on conflict do nothing;
 rows_count:=1;
end if;
v_result:=jsonb_build_object('source_rows',rows_count,'successor_jobs',enqueued,'next_cursor_present',cursor_value is not null,'company_membership','UNRESOLVED_NOT_RANKED','next_stage','BLOCKED_COMPANY_RECONCILIATION');
update population_top3000_202608_202609_v1.acquisition_job set status='COMPLETE',checkpoint='NORMALISED_PERSISTED',result=v_result,last_error=null,lease_until=null,updated_at=clock_timestamp() where job_id=jid;
update population_top3000_202608_202609_v1.acquisition_attempt set status='COMPLETE',result=v_result where attempt_id=p_attempt;
update population_top3000_202608_202609_v1.acquisition_control set last_useful_progress_at=clock_timestamp(),updated_at=clock_timestamp() where singleton;
insert into population_top3000_202608_202609_v1.acquisition_event(job_id,attempt_id,event,details) values(jid,p_attempt,'COMMITTED',v_result);
return jsonb_build_object('state','COMMITTED','job_id',jid,'result',v_result);
end $function$

functions.dispatch_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.dispatch_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare c population_top3000_202608_202609_v1.acquisition_control%rowtype;
j population_top3000_202608_202609_v1.acquisition_job%rowtype;a uuid;token text;rid bigint;recovered bigint;
begin
if not pg_try_advisory_xact_lock(2026083000261022) then return '{"state":"BUSY"}';end if;
select * into c from population_top3000_202608_202609_v1.acquisition_control where singleton for update;
if not found then return '{"state":"CONTROL_MISSING"}';end if;
if not c.enabled or c.stopped or c.hold_reason is not null then return jsonb_build_object('state','HOLD','reason',c.hold_reason);end if;
if c.admitted_until<=clock_timestamp() then return '{"state":"ADMISSION_EXPIRED"}';end if;
if c.dispatch_calls>=c.max_dispatch_calls or c.http_invocations>=c.max_http_invocations then return '{"state":"INVOCATION_LIMIT"}';end if;
update population_top3000_202608_202609_v1.acquisition_control set dispatch_calls=dispatch_calls+1 where singleton;
-- Reconcile only expired attempts. Retained raw outputs are never deleted or redownloaded.
with expired as (
 update population_top3000_202608_202609_v1.acquisition_attempt attempt_row set status='EXPIRED'
 from population_top3000_202608_202609_v1.acquisition_job job_row
 where job_row.status='LEASED' and job_row.lease_until<=clock_timestamp() and attempt_row.attempt_id=job_row.attempt_id and attempt_row.status in('DISPATCHED','CLAIMED','SOURCE_SAVED')
 returning attempt_row.reserved_bytes
) select coalesce(sum(reserved_bytes),0) into recovered from expired;
update population_top3000_202608_202609_v1.acquisition_control set reserved_bytes=greatest(0,reserved_bytes-recovered) where singleton;
insert into population_top3000_202608_202609_v1.acquisition_event(job_id,attempt_id,event,details)
select job_id,attempt_id,'LEASE_EXPIRED',jsonb_build_object('checkpoint',checkpoint,'attempts',attempts) from population_top3000_202608_202609_v1.acquisition_job where status='LEASED' and lease_until<=clock_timestamp();
update population_top3000_202608_202609_v1.acquisition_job set status=case when attempts<max_attempts and (case when last_error='LEASE_EXPIRED' then consecutive_error_count+1 else 1 end)<2 then 'READY' else 'BLOCKED' end,consecutive_error_count=case when last_error='LEASE_EXPIRED' then consecutive_error_count+1 else 1 end,last_error='LEASE_EXPIRED',lease_until=null,updated_at=clock_timestamp() where status='LEASED' and lease_until<=clock_timestamp();
if (select count(*) from population_top3000_202608_202609_v1.acquisition_job where status='LEASED' and lease_until>clock_timestamp())>=2 then return '{"state":"CONCURRENCY_LIMIT"}';end if;
select * into j from population_top3000_202608_202609_v1.acquisition_job
where status='READY' and attempts<max_attempts and not_before<=clock_timestamp()
and (c.next_provider_at<=clock_timestamp() or exists(select 1 from population_top3000_202608_202609_v1.acquisition_raw cached where cached.job_id=acquisition_job.job_id))
order by case when kind='CENSUS' then 0 else 1 end,page_number nulls last,job_id for update skip locked limit 1;
if not found then
 if exists(select 1 from population_top3000_202608_202609_v1.acquisition_job where status in('READY','LEASED')) then return '{"state":"BOUNDED_WAIT_FOR_READY_JOB"}';end if;
 update population_top3000_202608_202609_v1.acquisition_control set next_stage='BLOCKED_COMPANY_RECONCILIATION',next_action='Controller must reconcile company identities, class/ADR cap semantics, independent sources and cutoff; retain all blocked source jobs. Acquisition idle is not mission completion.' where singleton;
 return '{"state":"BLOCKED_COMPANY_RECONCILIATION"}';
end if;
a:=gen_random_uuid();token:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');
update population_top3000_202608_202609_v1.acquisition_job set status='LEASED',attempts=attempts+1,attempt_id=a,lease_until=clock_timestamp()+interval '90 seconds',owner_fence=c.owner_fence,stop_generation=c.stop_generation,updated_at=clock_timestamp() where job_id=j.job_id;
insert into population_top3000_202608_202609_v1.acquisition_attempt(attempt_id,job_id,attempt_number,token_sha256,owner_fence,stop_generation)
values(a,j.job_id,j.attempts+1,encode(sha256(convert_to(token,'UTF8')),'hex'),c.owner_fence,c.stop_generation);
select net.http_post(url:='https://oxzabweahkoimtevbbny.supabase.co/functions/v1/population-top3000-source-v1',headers:='{"Content-Type":"application/json"}'::jsonb,body:=jsonb_build_object('attempt_id',a,'token',token),timeout_milliseconds:=55000) into rid;
update population_top3000_202608_202609_v1.acquisition_attempt set request_id=rid where attempt_id=a;
update population_top3000_202608_202609_v1.acquisition_control set http_invocations=http_invocations+1 where singleton;
insert into population_top3000_202608_202609_v1.acquisition_event(job_id,attempt_id,event,details) values(j.job_id,a,'DISPATCHED',jsonb_build_object('request_id',rid,'fence',c.owner_fence,'stop_generation',c.stop_generation));
return jsonb_build_object('state','DISPATCHED','job_id',j.job_id,'attempt_id',a,'request_id',rid);
end $function$

functions.save_source_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.save_source_v1(p_attempt uuid, p_token text, p_raw text, p_sha text, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare jid text;b bigint;reserved bigint;existing_sha text;interrupt_test boolean;
begin
jid:=population_top3000_202608_202609_v1.assert_attempt_v1(p_attempt,p_token);
if not exists(select 1 from population_top3000_202608_202609_v1.acquisition_attempt where attempt_id=p_attempt and claimed_at is not null) then raise exception 'CLAIM_REQUIRED';end if;
b:=octet_length(p_raw);if b>8388608 or b<=0 or p_sha is distinct from encode(sha256(convert_to(p_raw,'UTF8')),'hex') then raise exception 'SOURCE_HASH_OR_SIZE_INVALID';end if;
perform p_raw::jsonb;
select sha256 into existing_sha from population_top3000_202608_202609_v1.acquisition_raw where job_id=jid;
if existing_sha is not null and existing_sha<>p_sha then raise exception 'IMMUTABLE_SOURCE_CONFLICT';end if;
select reserved_bytes into reserved from population_top3000_202608_202609_v1.acquisition_attempt where attempt_id=p_attempt;
if existing_sha is null then
 insert into population_top3000_202608_202609_v1.acquisition_raw(job_id,raw_text,sha256,source_bytes,evidence) values(jid,p_raw,p_sha,b,p_evidence);
 update population_top3000_202608_202609_v1.acquisition_control set stored_bytes=stored_bytes+b,reserved_bytes=greatest(0,reserved_bytes-reserved),last_useful_progress_at=clock_timestamp(),updated_at=clock_timestamp() where singleton;
end if;
update population_top3000_202608_202609_v1.acquisition_attempt set reserved_bytes=0,status='SOURCE_SAVED' where attempt_id=p_attempt;
select interrupt_once and not interrupted into interrupt_test from population_top3000_202608_202609_v1.acquisition_job where job_id=jid;
update population_top3000_202608_202609_v1.acquisition_job set checkpoint='SOURCE_SAVED',interrupted=interrupted or interrupt_test,updated_at=clock_timestamp() where job_id=jid;
insert into population_top3000_202608_202609_v1.acquisition_event(job_id,attempt_id,event,details) values(jid,p_attempt,case when interrupt_test then 'INTERRUPTION_CHECKPOINT_SAVED' else 'SOURCE_SAVED' end,jsonb_build_object('bytes',b,'sha256',p_sha,'reused',existing_sha is not null));
return jsonb_build_object('state',case when interrupt_test then 'INTERRUPT_CHECKPOINT_TEST' else 'SOURCE_SAVED' end,'sha256',p_sha,'bytes',b);
end $function$

functions.macro_derive_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.macro_derive_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;h text;n integer;
begin
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);select * into t from population_top3000_202608_202609_v1.pipeline_task where task_id=tid;
 select count(*),encode(sha256(convert_to(string_agg(unit_key||':'||record_sha256||E'\n','' order by unit_key),'UTF8')),'hex') into n,h from population_top3000_202608_202609_v1.source_observation where family_id='CTX07' and partition_key=t.partition_key;
 if n=0 then raise exception 'MACRO_SOURCE_POPULATION_MISSING';end if;
 -- Prior-release values were computed as strictly earlier headlines by the normalizer.
 -- Consensus/surprise are outside the existing official-headline dictionary and stay null.
 return jsonb_build_object('state','COMPLETE','commit_receipt',jsonb_build_object('commit_key','macro-derive:'||t.partition_key||':'||h,'input_versions',t.input_versions,'immutable_output_ids',jsonb_build_array('CTX07:'||t.partition_key),'output_sha256',h,'new_committed_units',0,'derivation','Earlier-publication prior print already materialized; no research transformations'));
end $function$

functions.query_cursor_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.query_cursor_v1(p_url text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
declare encoded text;decoded bytea:=''::bytea;i integer:=1;c text;
begin
if p_url !~ '^https://api[.](massive[.]com|polygon[.]io)/v3/reference/tickers[?]' then return null;end if;
encoded:=substring(p_url from '[?&]cursor=([^&#]*)');if encoded is null then return null;end if;
while i<=length(encoded) loop
 c:=substring(encoded from i for 1);
 if c='%' then
  if substring(encoded from i+1 for 2) !~ '^[0-9a-fA-F]{2}$' then return null;end if;
  decoded:=decoded||decode(substring(encoded from i+1 for 2),'hex');i:=i+3;
 else decoded:=decoded||convert_to(case when c='+' then ' ' else c end,'UTF8');i:=i+1;
 end if;
end loop;
return convert_from(decoded,'UTF8');
exception when others then return null;
end $function$

functions.pipeline_fail_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_fail_v1(p_attempt uuid, p_token text, p_class text, p_fingerprint text, p_details jsonb, p_retry_after_seconds integer DEFAULT 60)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;same integer;retry boolean;
begin
tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
select * into t from population_top3000_202608_202609_v1.pipeline_task where task_id=tid;
if p_class is null or p_class not in('RATE_LIMIT','LOCK','TRANSPORT_READ','UNCERTAIN_EFFECT','AUTHENTICATION','OWNERSHIP','CODE_INTEGRITY','PARSER','SOURCE_ABSENT','QUALITY','BUDGET','LEASE_EXPIRED') or nullif(p_fingerprint,'') is null or p_retry_after_seconds is null or p_retry_after_seconds<0 then raise exception 'DIAGNOSED_FAILURE_REQUIRED';end if;
same:=case when t.last_failure_fingerprint=p_fingerprint then t.same_failure_count+1 else 1 end;
retry:=p_class in('RATE_LIMIT','LOCK','TRANSPORT_READ') and same<2 and t.cumulative_failures+1<t.max_failures;
if exists(select 1 from population_top3000_202608_202609_v1.pipeline_provider_lease where attempt_id=p_attempt and released_at is null) then retry:=false;p_class:='UNCERTAIN_EFFECT';end if;
if p_class='RATE_LIMIT' then update population_top3000_202608_202609_v1.acquisition_control set next_provider_at=greatest(next_provider_at,clock_timestamp()+make_interval(secs=>p_retry_after_seconds)) where singleton;end if;
update population_top3000_202608_202609_v1.pipeline_task set status=case when retry then 'READY' else 'BLOCKED' end,cumulative_failures=cumulative_failures+1,same_failure_count=same,last_failure_class=p_class,last_failure_fingerprint=p_fingerprint,lease_until=case when p_class='UNCERTAIN_EFFECT' and exists(select 1 from population_top3000_202608_202609_v1.pipeline_provider_lease pl where pl.attempt_id=p_attempt and pl.released_at is null) then lease_until else null end,not_before=clock_timestamp()+make_interval(secs=>p_retry_after_seconds),blocker_code=case when retry then null else p_class end,resumption_condition=case when retry then null else jsonb_build_object('required_action',case p_class when 'UNCERTAIN_EFFECT' then 'Reconcile immutable output and billing receipts before retry.' when 'SOURCE_ABSENT' then 'Supply historical source or bounded reviewed alternate-source adapter.' when 'QUALITY' then 'Deploy diagnosed targeted repair with new input revision and reverify.' else 'Diagnose cause and apply reviewed changed approach; do not reset counters.'end,'details',p_details)end where task_id=tid;
update population_top3000_202608_202609_v1.pipeline_attempt set outcome=case when retry then 'RETRY_SCHEDULED' else 'BLOCKED' end,ended_at=clock_timestamp() where attempt_id=p_attempt;
insert into population_top3000_202608_202609_v1.pipeline_event(task_id,attempt_id,event,details)values(tid,p_attempt,'FAILURE',jsonb_build_object('class',p_class,'fingerprint',p_fingerprint,'same_count',same,'retry',retry,'details',p_details));
return jsonb_build_object('state',case when retry then 'RETRY_SCHEDULED' else 'BLOCKED' end);
end $function$

functions.pipeline_tick_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_tick_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c population_top3000_202608_202609_v1.acquisition_control%rowtype;p population_top3000_202608_202609_v1.pipeline_control%rowtype;
 t population_top3000_202608_202609_v1.pipeline_task%rowtype;b population_top3000_202608_202609_v1.pipeline_adapter%rowtype;
 x record;a uuid;tok text;fn text;receipt jsonb;result jsonb;err text;errstate text;h text;wake timestamptz;ready_count bigint;hold_state text;
begin
 if not pg_try_advisory_xact_lock(2026083000261022) then return '{"state":"BUSY"}';end if;
 select * into c from population_top3000_202608_202609_v1.acquisition_control where singleton for update;
 select * into p from population_top3000_202608_202609_v1.pipeline_control where singleton for update;
 -- Never alter an unrelated scheduler job if the mission binding has changed.
 if not exists(select 1 from cron.job where jobid=596 and database=current_database()
  and btrim(command)='select population_top3000_202608_202609_v1.pipeline_tick_v1();') then
  return '{"state":"SCHEDULER_BINDING_MISMATCH"}';
 end if;
 if p.singleton is null or c.singleton is null then hold_state:='CONTROL_MISSING';
 elsif c.owner_id is distinct from p.expected_owner_id or c.owner_fence is distinct from p.expected_owner_fence or c.stop_generation is distinct from p.expected_stop_generation then hold_state:='OWNER_OR_STOP_CHANGED';
 elsif c.scope_sha256 is distinct from '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' or p.scope_sha256 is distinct from c.scope_sha256 then hold_state:='SCOPE_MISMATCH';
 elsif c.stopped is distinct from false or c.enabled is distinct from true or c.hold_reason is not null or p.enabled is distinct from true then hold_state:='HELD';
 end if;
 if hold_state is not null then
  -- Disarm this bound mission job without changing either owner's state, holds or fences.
  if exists(select 1 from cron.job where jobid=596 and active) then
   perform cron.alter_job(596,active=>false);
   insert into population_top3000_202608_202609_v1.pipeline_event(event,details) values('HOLD_DISARMED',
    jsonb_build_object('reason',hold_state,'owner_id',c.owner_id,'owner_fence',c.owner_fence,'stop_generation',c.stop_generation,'expected_owner_id',p.expected_owner_id,'expected_owner_fence',p.expected_owner_fence,'expected_stop_generation',p.expected_stop_generation));
  end if;
  return jsonb_build_object('state',hold_state);
 end if;
 if not p.shared_scheduler_verified then
  insert into population_top3000_202608_202609_v1.pipeline_event(event,details) values('SCHEDULER_PROBE',jsonb_build_object('backend_pid',pg_backend_pid(),'application_name',current_setting('application_name'),'database_user',current_user,'owner_id',c.owner_id,'owner_fence',c.owner_fence,'stop_generation',c.stop_generation,'no_task_executed',true));
  perform cron.alter_job(596,active=>false);
  return '{"state":"SCHEDULER_PROBE_RECORDED_AWAITING_EVIDENCE_REVIEW"}';
 end if;
 if p.budget_verified_at is null or jsonb_typeof(p.budget_evidence) is distinct from 'object'
  or (p.actual_usd+p.accrued_usd+p.unavoidable_usd+p.remaining_uncommitted_usd+p.repair_egress_reserve_usd+p.reserved_request_usd<=p.budget_cap_usd) is distinct from true then
  if exists(select 1 from cron.job where jobid=596 and active) then
   perform cron.alter_job(596,active=>false);
   insert into population_top3000_202608_202609_v1.pipeline_event(event,details) values('HOLD_DISARMED',jsonb_build_object('reason','BUDGET_HOLD','owner_fence',c.owner_fence));
  end if;
  return '{"state":"BUDGET_HOLD"}';
 end if;
 if c.admitted_until is null or c.admitted_until<=clock_timestamp() or p.deadline is null or p.deadline<=clock_timestamp() or p.tick_count>=p.max_ticks then
  perform cron.alter_job(596,active=>false);
  insert into population_top3000_202608_202609_v1.pipeline_event(event,details) values('ADMISSION_EXPIRED_OR_TICK_LIMIT',jsonb_build_object('admitted_until',c.admitted_until,'deadline',p.deadline,'ticks',p.tick_count));
  return '{"state":"ADMISSION_EXPIRED_OR_TICK_LIMIT"}';end if;
 if p.next_wakeup_at>clock_timestamp() then return jsonb_build_object('state','SCHEDULED_WAIT','not_before',p.next_wakeup_at);end if;
 update population_top3000_202608_202609_v1.pipeline_control set tick_count=tick_count+1 where singleton;
 -- Expired effects are reconciled by immutable receipts. A reserved provider charge is conservatively accrued.
 for x in select q.*,exists(select 1 from population_top3000_202608_202609_v1.pipeline_provider_lease pl where pl.attempt_id=q.attempt_id and pl.released_at is null) as uncertain_provider_effect from population_top3000_202608_202609_v1.pipeline_task q where q.status='LEASED' and q.lease_until<=clock_timestamp() for update of q loop
  update population_top3000_202608_202609_v1.pipeline_control set accrued_usd=accrued_usd+coalesce((select sum(reserved_usd) from population_top3000_202608_202609_v1.pipeline_provider_lease where attempt_id=x.attempt_id and released_at is null),0),reserved_request_usd=reserved_request_usd-coalesce((select sum(reserved_usd) from population_top3000_202608_202609_v1.pipeline_provider_lease where attempt_id=x.attempt_id and released_at is null),0) where singleton;
  update population_top3000_202608_202609_v1.acquisition_control set reserved_bytes=greatest(0,reserved_bytes-coalesce((select sum(reserved_bytes) from population_top3000_202608_202609_v1.pipeline_provider_lease where attempt_id=x.attempt_id and released_at is null),0)) where singleton;
  update population_top3000_202608_202609_v1.pipeline_provider_lease set released_at=clock_timestamp(),actual_usd=reserved_usd,outcome='EXPIRED_CONSERVATIVELY_ACCRUED' where attempt_id=x.attempt_id and released_at is null;
  update population_top3000_202608_202609_v1.pipeline_attempt set outcome=case when x.uncertain_provider_effect then 'BLOCKED' else 'LEASE_EXPIRED_RECONCILED' end,ended_at=clock_timestamp() where attempt_id=x.attempt_id and outcome='RUNNING';
  update population_top3000_202608_202609_v1.pipeline_task set status=case when not x.uncertain_provider_effect and cumulative_failures+1<max_failures and (last_failure_class is distinct from 'LEASE_EXPIRED' or same_failure_count<1) then 'READY' else 'BLOCKED' end,
   cumulative_failures=cumulative_failures+1,same_failure_count=case when last_failure_class='LEASE_EXPIRED' then same_failure_count+1 else 1 end,last_failure_class=case when x.uncertain_provider_effect then 'UNCERTAIN_EFFECT' else 'LEASE_EXPIRED' end,last_failure_fingerprint=case when x.uncertain_provider_effect then 'LEASE_EXPIRED_UNCERTAIN_PROVIDER' else 'LEASE_EXPIRED' end,
   blocker_code=case when not x.uncertain_provider_effect and cumulative_failures+1<max_failures and (last_failure_class is distinct from 'LEASE_EXPIRED' or same_failure_count<1) then null else case when x.uncertain_provider_effect then 'UNCERTAIN_EFFECT' else 'LEASE_EXPIRED' end end,
   resumption_condition=case when not x.uncertain_provider_effect and cumulative_failures+1<max_failures and (last_failure_class is distinct from 'LEASE_EXPIRED' or same_failure_count<1) then null else jsonb_build_object('required_action',case when x.uncertain_provider_effect then 'Reconcile immutable output and actual billing receipts before any retry; expired provider reservation was conservatively accrued and no retry is admitted.' else 'Inspect retained source/commit hashes and worker response, apply changed approach before retry' end) end,
   lease_until=null,not_before=greatest(clock_timestamp()+interval '30 seconds',c.next_provider_at) where task_id=x.task_id;
  insert into population_top3000_202608_202609_v1.pipeline_event(task_id,attempt_id,event,details)values(x.task_id,x.attempt_id,'EXPIRED_RECONCILED',jsonb_build_object('checkpoint',x.checkpoint,'retained_commits',(select count(*) from population_top3000_202608_202609_v1.pipeline_commit where task_id=x.task_id)));
 end loop;
 -- A failed external attempt remains blocked; only its expired reservation is released.
 -- pipeline_fail_v1 preserves the original lease deadline when effects are uncertain.
 for x in select q.* from population_top3000_202608_202609_v1.pipeline_task q
  where q.status='BLOCKED' and q.blocker_code='UNCERTAIN_EFFECT'
   and q.lease_until is not null and q.lease_until<=clock_timestamp()
   and exists(select 1 from population_top3000_202608_202609_v1.pipeline_provider_lease pl where pl.attempt_id=q.attempt_id and pl.released_at is null)
  for update of q loop
  update population_top3000_202608_202609_v1.pipeline_control set
   accrued_usd=accrued_usd+coalesce((select sum(pl.reserved_usd) from population_top3000_202608_202609_v1.pipeline_provider_lease pl where pl.attempt_id=x.attempt_id and pl.released_at is null),0),
   reserved_request_usd=reserved_request_usd-coalesce((select sum(pl.reserved_usd) from population_top3000_202608_202609_v1.pipeline_provider_lease pl where pl.attempt_id=x.attempt_id and pl.released_at is null),0) where singleton;
  update population_top3000_202608_202609_v1.acquisition_control set reserved_bytes=reserved_bytes-coalesce((select sum(pl.reserved_bytes) from population_top3000_202608_202609_v1.pipeline_provider_lease pl where pl.attempt_id=x.attempt_id and pl.released_at is null),0) where singleton;
  update population_top3000_202608_202609_v1.pipeline_provider_lease set released_at=clock_timestamp(),actual_usd=reserved_usd,outcome='UNCERTAIN_EFFECT_CONSERVATIVELY_ACCRUED' where attempt_id=x.attempt_id and released_at is null;
  update population_top3000_202608_202609_v1.pipeline_task set lease_until=null,
   resumption_condition=coalesce(resumption_condition,'{}'::jsonb)||jsonb_build_object('required_action','Reconcile immutable output and actual billing receipts before any retry. Reservation was conservatively accrued after its original deadline; task remains blocked.','reservation_reconciled_at',clock_timestamp()) where task_id=x.task_id;
  insert into population_top3000_202608_202609_v1.pipeline_event(task_id,attempt_id,event,details) values(x.task_id,x.attempt_id,'UNCERTAIN_RESERVATION_RECONCILED',jsonb_build_object('original_deadline',x.lease_until,'task_remains_blocked',true,'retry_admitted',false));
 end loop;
 -- Only explicitly timed temporary conditions are rechecked. Auth, budget, code and user holds never auto-release.
 update population_top3000_202608_202609_v1.pipeline_task q set status='READY',recheck_count=recheck_count+1,blocker_until=null,blocker_code=null,resumption_condition=null
 where q.status='BLOCKED' and q.blocker_until<=clock_timestamp() and q.recheck_count<q.max_rechecks
 and q.blocker_code in('DEPENDENCY_PENDING','RETAINED_IMPORT_PENDING','RETAINED_SEC_SOURCE_IMPORT_INCOMPLETE','ADAPTER_NOT_INSTALLED')
 and exists(select 1 from population_top3000_202608_202609_v1.pipeline_adapter adapter_rows where adapter_rows.family_id=q.family_id and adapter_rows.stage=q.stage and adapter_rows.enabled);
 -- Executions are bounded independently of failure count. Do not leave exhausted work READY.
 for x in update population_top3000_202608_202609_v1.pipeline_task q
  set status='BLOCKED',blocker_code='EXECUTION_LIMIT',blocker_until=null,
   resumption_condition=jsonb_build_object('required_action','Review retained checkpoint, immutable outputs and measured batch size; admit an explicitly bounded changed approach without resetting counters.','executions',q.executions,'max_executions',q.max_executions)
  where q.status='READY' and q.executions>=q.max_executions
  returning q.task_id,q.attempt_id,q.executions,q.max_executions loop
  insert into population_top3000_202608_202609_v1.pipeline_event(task_id,attempt_id,event,details) values(x.task_id,x.attempt_id,'EXECUTION_LIMIT_BLOCKED',jsonb_build_object('executions',x.executions,'max_executions',x.max_executions));
 end loop;
 if (select count(*) from population_top3000_202608_202609_v1.pipeline_task where status='LEASED' and lease_until>clock_timestamp())>=p.max_active_tasks then return '{"state":"CONCURRENCY_LIMIT"}';end if;
 select q.* into t from population_top3000_202608_202609_v1.pipeline_task q
 left join population_top3000_202608_202609_v1.pipeline_adapter adapter_rows on adapter_rows.family_id=q.family_id and adapter_rows.stage=q.stage
 where q.status='READY' and q.not_before<=clock_timestamp() and q.executions<q.max_executions
 and not exists(select 1 from population_top3000_202608_202609_v1.pipeline_dependency d join population_top3000_202608_202609_v1.pipeline_task z on z.task_id=d.prerequisite_task_id where d.task_id=q.task_id and z.status<>'COMPLETE')
 and (adapter_rows.resource_class is distinct from 'PROVIDER' or (c.next_provider_at<=clock_timestamp() and not exists(select 1 from population_top3000_202608_202609_v1.pipeline_provider_lease where released_at is null)))
 order by (adapter_rows.enabled is true) desc, q.executions,q.created_at,q.task_id for update of q skip locked limit 1;
 if not found then
  select min(q.not_before) into wake from population_top3000_202608_202609_v1.pipeline_task q where status='READY' and not_before>clock_timestamp();
  if exists(select 1 from population_top3000_202608_202609_v1.pipeline_task where status='LEASED') then wake:=least(coalesce(wake,'infinity'),clock_timestamp()+interval '5 seconds');
  elsif exists(select 1 from population_top3000_202608_202609_v1.pipeline_task where status='READY') then wake:=least(coalesce(wake,'infinity'),greatest(c.next_provider_at,clock_timestamp()+interval '30 seconds'));
  else wake:=least(coalesce(wake,'infinity'),clock_timestamp()+interval '5 minutes');end if;
  update population_top3000_202608_202609_v1.pipeline_control set next_wakeup_at=wake,idle_rechecks=idle_rechecks+1,wake_reason='WAIT_FOR_READY_TASK_OR_EVIDENCE' where singleton;
  if not exists(select 1 from population_top3000_202608_202609_v1.pipeline_task where status in('READY','LEASED')) and p.idle_rechecks>=p.max_idle_rechecks then
   update population_top3000_202608_202609_v1.pipeline_control set enabled=false,wake_reason='BOUNDED_WAIT_EXHAUSTED_REQUIRES_NEW_EVIDENCE' where singleton;
   perform cron.alter_job(596,schedule=>'*/5 * * * *',active=>false);
   insert into population_top3000_202608_202609_v1.pipeline_event(event,details)values('BOUNDED_WAIT_DISARMED',jsonb_build_object('resumption','New authorised evidence/adapters admitted by controller; preserve attempts and counters'));
  elsif not exists(select 1 from population_top3000_202608_202609_v1.pipeline_task where status='LEASED') then perform cron.alter_job(596,schedule=>'*/1 * * * *');end if;
  return jsonb_build_object('state','BOUNDED_WAIT','not_before',wake);
 end if;
 select * into b from population_top3000_202608_202609_v1.pipeline_adapter where family_id=t.family_id and stage=t.stage;
 if not found or not b.enabled then
  update population_top3000_202608_202609_v1.pipeline_task set status='BLOCKED',blocker_code='ADAPTER_NOT_INSTALLED',resumption_condition=jsonb_build_object('family',t.family_id,'stage',t.stage,'required_action','Install reviewed scoped adapter'),blocker_until=clock_timestamp()+interval '5 minutes' where task_id=t.task_id;
  return jsonb_build_object('state','ADAPTER_NOT_INSTALLED','task_id',t.task_id);
 end if;
 h:=encode(sha256(convert_to(pg_get_functiondef(b.function_oid),'UTF8')),'hex');
 if h is distinct from b.function_sha256 then
  update population_top3000_202608_202609_v1.pipeline_task set status='BLOCKED',blocker_code='CODE_INTEGRITY',resumption_condition=jsonb_build_object('required_action','Reconcile changed adapter definition and tests; bind reviewed revision') where task_id=t.task_id;return '{"state":"CODE_INTEGRITY_HOLD"}';
 end if;
 a:=gen_random_uuid();tok:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-','');
 update population_top3000_202608_202609_v1.pipeline_task set status='LEASED',attempt_id=a,lease_until=least(clock_timestamp()+interval '90 seconds',c.admitted_until),owner_fence=c.owner_fence,stop_generation=c.stop_generation,executions=executions+1,started_at=coalesce(started_at,clock_timestamp()) where task_id=t.task_id;
 insert into population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256) values(a,t.task_id,t.executions+1,encode(sha256(convert_to(tok,'UTF8')),'hex'),c.owner_fence,c.stop_generation,b.function_sha256);
 update population_top3000_202608_202609_v1.pipeline_control set next_wakeup_at=clock_timestamp(),idle_rechecks=0,wake_reason=null where singleton;
 perform cron.alter_job(596,schedule=>'2 seconds');
 update population_top3000_202608_202609_v1.acquisition_control set next_stage='PIPELINE_EXECUTION',next_action=t.family_id||'/'||t.stage||'/'||t.partition_key where singleton;
 select format('%I.%I',n.nspname,r.proname) into fn from pg_proc r join pg_namespace n on n.oid=r.pronamespace where r.oid=b.function_oid and r.pronargs=2 and r.proargtypes[0]='uuid'::regtype and r.proargtypes[1]='text'::regtype;
 begin
  if fn is null then raise exception 'INVALID_ADAPTER_SIGNATURE';end if;
  execute format('select %s($1,$2)',fn) into receipt using a,tok;
  if receipt->>'state'='ASYNC' then result:=receipt;
  elsif (select outcome from population_top3000_202608_202609_v1.pipeline_attempt where attempt_id=a)<>'RUNNING' then result:=receipt;
  else result:=population_top3000_202608_202609_v1.pipeline_finish_v1(a,tok,receipt);end if;
 exception when others then
  get stacked diagnostics err=MESSAGE_TEXT,errstate=RETURNED_SQLSTATE;
  result:=population_top3000_202608_202609_v1.pipeline_fail_v1(a,tok,case when errstate in('55P03','40P01') then 'LOCK' else 'PARSER' end,errstate||':'||left(err,150),jsonb_build_object('sqlstate',errstate,'message',left(err,500)),60);
 end;
 insert into population_top3000_202608_202609_v1.pipeline_event(task_id,attempt_id,event,details)values(t.task_id,a,'DISPATCHED',jsonb_build_object('family',t.family_id,'stage',t.stage,'partition',t.partition_key,'resource',b.resource_class,'result',result));
 return jsonb_build_object('state','DISPATCHED','task_id',t.task_id,'attempt_id',a,'result',result);
end $function$

functions.pipeline_wake_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_wake_v1(p_owner text, p_fence bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare c population_top3000_202608_202609_v1.acquisition_control%rowtype;
 p population_top3000_202608_202609_v1.pipeline_control%rowtype;
begin
 perform pg_advisory_xact_lock(2026083000261022);
 select * into c from population_top3000_202608_202609_v1.acquisition_control where singleton for update;
 select * into p from population_top3000_202608_202609_v1.pipeline_control where singleton for update;
 if c.singleton is null or p.singleton is null then raise exception 'CONTROL_MISSING';end if;
 if p_owner is null or p_fence is null or c.owner_id is distinct from p_owner or c.owner_fence is distinct from p_fence
  or p.expected_owner_id is distinct from c.owner_id or p.expected_owner_fence is distinct from c.owner_fence or p.expected_stop_generation is distinct from c.stop_generation then raise exception 'OWNER_OR_STOP_CHANGED';end if;
 if c.scope_sha256 is distinct from '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' or p.scope_sha256 is distinct from c.scope_sha256 then raise exception 'SCOPE_MISMATCH';end if;
 if c.stopped is distinct from false or c.enabled is distinct from true or c.hold_reason is not null
  or c.admitted_until is null or c.admitted_until<=clock_timestamp() then raise exception 'OWNER_STOP_OR_ADMISSION';end if;
 if p.deadline is null or p.deadline<=clock_timestamp() or p.tick_count>=p.max_ticks then raise exception 'DEADLINE_OR_TICK_LIMIT';end if;
 if p.shared_scheduler_verified is distinct from true then raise exception 'SCHEDULER_EVIDENCE_REQUIRED';end if;
 if p.budget_verified_at is null or jsonb_typeof(p.budget_evidence) is distinct from 'object'
  or (p.actual_usd+p.accrued_usd+p.unavoidable_usd+p.remaining_uncommitted_usd+p.repair_egress_reserve_usd+p.reserved_request_usd<=p.budget_cap_usd) is distinct from true then raise exception 'BUDGET_HOLD';end if;
 if nullif(btrim(p_reason),'') is null then raise exception 'WAKE_REASON_REQUIRED';end if;
 if not exists(select 1 from cron.job where jobid=596 and database=current_database()
  and btrim(command)='select population_top3000_202608_202609_v1.pipeline_tick_v1();') then raise exception 'SCHEDULER_BINDING_MISMATCH';end if;
 -- This operation admits a wake, never reconciles ownership or clears a user/budget hold.
 update population_top3000_202608_202609_v1.pipeline_control set enabled=true,next_wakeup_at=clock_timestamp(),idle_rechecks=0,wake_reason=p_reason where singleton;
 perform cron.alter_job(596,schedule=>'2 seconds',active=>true);
 insert into population_top3000_202608_202609_v1.pipeline_event(event,details)values('WAKE_ADMITTED',jsonb_build_object('owner',p_owner,'fence',p_fence,'stop_generation',c.stop_generation,'scope_sha256',c.scope_sha256,'reason',p_reason));
 return '{"state":"SCHEDULED"}';
end $function$

functions.assert_attempt_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.assert_attempt_v1(p_attempt uuid, p_token text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare c population_top3000_202608_202609_v1.acquisition_control%rowtype;a population_top3000_202608_202609_v1.acquisition_attempt%rowtype;j population_top3000_202608_202609_v1.acquisition_job%rowtype;
begin
select * into c from population_top3000_202608_202609_v1.acquisition_control where singleton for update;
if not found then raise exception 'CONTROL_MISSING';end if;
select * into a from population_top3000_202608_202609_v1.acquisition_attempt where attempt_id=p_attempt for update;
if a.attempt_id is null or a.token_sha256 is distinct from encode(sha256(convert_to(p_token,'UTF8')),'hex') then raise exception 'AUTHENTICATION_FAILED';end if;
select * into j from population_top3000_202608_202609_v1.acquisition_job where job_id=a.job_id for update;
if not c.enabled or c.stopped or c.hold_reason is not null or c.admitted_until<=clock_timestamp() then raise exception 'MISSION_STOPPED_OR_HELD';end if;
if j.status is distinct from 'LEASED' or j.attempt_id is distinct from p_attempt or j.lease_until is null or j.lease_until<=clock_timestamp() then raise exception 'LEASE_LOST';end if;
if a.owner_fence is distinct from c.owner_fence or a.stop_generation is distinct from c.stop_generation or j.owner_fence is distinct from c.owner_fence or j.stop_generation is distinct from c.stop_generation then raise exception 'STALE_FENCE';end if;
return j.job_id;
end $function$

functions.company_derive_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.company_derive_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;v jsonb;
begin
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 select * into t from population_top3000_202608_202609_v1.pipeline_task where task_id=tid;
 if t.family_id<>'REF01' or t.stage<>'DERIVE' then raise exception 'COMPANY_ADAPTER_SCOPE_MISMATCH';end if;
 v:=jsonb_build_object('state','PROVISIONAL','screening_rule','One CIK review group; max vendor cap for triage only; never sum repeated company vendor caps',
  'screening_cutoff',(select jsonb_build_object('group_key',group_key,'tickers',candidate_tickers,'vendor_cap_screen',vendor_cap_screen_max)from population_top3000_202608_202609_v1.company_group_v1 where screening_rank=3000),
  'open_exceptions',(select count(*)from population_top3000_202608_202609_v1.company_exception_v1 where status='OPEN'),
  'company_universe_frozen',false,'known_original_historical_receipt_not_required_for_source_progress',true);
 if t.partition_key='company-census' then
  update population_top3000_202608_202609_v1.pipeline_universe set status='PROVISIONAL',
   cutoff_evidence=v,unresolved_cutoff_cases=(select count(*)from population_top3000_202608_202609_v1.company_group_v1),
   unresolved_instrument_cases=(select count(*)from population_top3000_202608_202609_v1.company_candidate_v1 where classification<>'TYPE_EXCLUSION_CANDIDATE') where singleton and status<>'FROZEN';
 end if;
 return population_top3000_202608_202609_v1.pipeline_finish_v1(p_attempt,p_token,jsonb_build_object('state','COMPLETE','commit_receipt',
  jsonb_build_object('commit_key','company-derive:'||t.operation_key,'output_sha256',encode(sha256(convert_to(v::text,'UTF8')),'hex'),
   'new_committed_units',1,'immutable_output_ids',jsonb_build_array(t.partition_key),'input_versions',t.input_versions,'evidence',v)));
end $function$

functions.pipeline_finish_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_finish_v1(p_attempt uuid, p_token text, p_receipt jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;state text;next_stage text;next_id uuid;fresh boolean;at_time timestamptz;
 a population_top3000_202608_202609_v1.pipeline_attempt%rowtype;part jsonb;v population_top3000_202608_202609_v1.pipeline_validation%rowtype;
begin
 select * into a from population_top3000_202608_202609_v1.pipeline_attempt where attempt_id=p_attempt;
 if a.token_sha256=encode(sha256(convert_to(p_token,'UTF8')),'hex') and a.outcome in('COMPLETE','CONTINUE','BLOCKED') then return jsonb_build_object('state','ALREADY_RECORDED','outcome',a.outcome);end if;
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 select * into t from population_top3000_202608_202609_v1.pipeline_task where task_id=tid;
 state:=p_receipt->>'state';
 if state is null or state not in('COMPLETE','CONTINUE','BLOCKED') then raise exception 'INVALID_FINISH_STATE';end if;
 if exists(select 1 from population_top3000_202608_202609_v1.pipeline_provider_lease where attempt_id=p_attempt and released_at is null) then raise exception 'PROVIDER_RESERVATION_MUST_BE_RECONCILED';end if;
 if state='BLOCKED' then
  if nullif(p_receipt->>'blocker_code','') is null or jsonb_typeof(p_receipt->'resumption_condition') is distinct from 'object' then raise exception 'SPECIFIC_BLOCKER_REQUIRED';end if;
  update population_top3000_202608_202609_v1.pipeline_task set status='BLOCKED',blocker_code=p_receipt->>'blocker_code',resumption_condition=p_receipt->'resumption_condition',blocker_until=nullif(p_receipt->>'recheck_at','')::timestamptz,lease_until=null where task_id=tid;
 else
  fresh:=population_top3000_202608_202609_v1.pipeline_record_commit_v1(p_attempt,p_token,p_receipt->'commit_receipt');
  if state='CONTINUE' then
   if jsonb_typeof(p_receipt->'checkpoint') is distinct from 'object' then raise exception 'CONTINUATION_CHECKPOINT_REQUIRED';end if;
   at_time:=coalesce(nullif(p_receipt->>'not_before','')::timestamptz,clock_timestamp());
   if not fresh and (p_receipt->'checkpoint') is not distinct from t.checkpoint and at_time<=clock_timestamp() then raise exception 'CONTINUATION_WITHOUT_PROGRESS_OR_WAIT';end if;
   update population_top3000_202608_202609_v1.pipeline_task set status='READY',checkpoint=p_receipt->'checkpoint',not_before=at_time,lease_until=null,same_failure_count=0 where task_id=tid;
  else
   if t.stage='PLAN' then
    if jsonb_typeof(p_receipt->'partitions') is distinct from 'array' or jsonb_array_length(p_receipt->'partitions')=0 or jsonb_array_length(p_receipt->'partitions')>1000 then raise exception 'PLAN_REQUIRES_BOUNDED_REAL_PARTITIONS';end if;
    for part in select value from jsonb_array_elements(p_receipt->'partitions')loop
     next_id:=population_top3000_202608_202609_v1.pipeline_enqueue_v1(t.family_id,'ACQUIRE',part->>'partition_key',coalesce(part->'payload','{}'),part->'input_versions',tid);
    end loop;
   elsif t.stage='VALIDATE' then
    select x.* into v from population_top3000_202608_202609_v1.pipeline_validation x join population_top3000_202608_202609_v1.pipeline_partition q on q.last_validation_id=x.validation_id
    where q.family_id=t.family_id and q.partition_key=t.partition_key and x.input_versions=t.input_versions and x.validation_id=(p_receipt->>'validation_id')::uuid;
    if not found or v.result is distinct from p_receipt->>'quality_result' then raise exception 'PERSISTED_VALIDATION_RECEIPT_REQUIRED';end if;
    next_stage:=case when v.result='PASS' or t.repair_round>=1 then 'PUBLISH' else 'REPAIR' end;
   elsif t.stage='PUBLISH' then next_stage:='DELIVER';
   elsif t.stage='REPAIR' then
    if t.repair_round>=2 then raise exception 'REPAIR_ROUND_LIMIT';end if;
    next_id:=population_top3000_202608_202609_v1.pipeline_enqueue_round_v1(t.family_id,'VALIDATE',t.partition_key,t.payload,t.input_versions,t.repair_round+1,tid);
   elsif t.stage='ACQUIRE' then next_stage:='NORMALIZE';
   elsif t.stage='NORMALIZE' then next_stage:='DERIVE';
   elsif t.stage='DERIVE' then next_stage:='VALIDATE';
   end if;
   update population_top3000_202608_202609_v1.pipeline_task set status='COMPLETE',completed_at=clock_timestamp(),lease_until=null,same_failure_count=0 where task_id=tid;
   if next_stage is not null then
    next_id:=population_top3000_202608_202609_v1.pipeline_enqueue_v1(t.family_id,next_stage,t.partition_key,t.payload,t.input_versions,tid);
    update population_top3000_202608_202609_v1.pipeline_task set repair_round=greatest(repair_round,t.repair_round) where task_id=next_id;
   end if;
  end if;
 end if;
 update population_top3000_202608_202609_v1.pipeline_attempt set outcome=state,ended_at=clock_timestamp() where attempt_id=p_attempt;
 insert into population_top3000_202608_202609_v1.pipeline_event(task_id,attempt_id,event,details)values(tid,p_attempt,state,(p_receipt-'commit_receipt')||jsonb_build_object('successor_task_id',next_id));
 return jsonb_build_object('state',state,'task_id',tid,'successor_task_id',next_id);
end $function$

functions.pipeline_repair_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_repair_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;v population_top3000_202608_202609_v1.pipeline_validation%rowtype;
 m jsonb;item record;n bigint:=0;out_hash text;
begin
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 select * into t from population_top3000_202608_202609_v1.pipeline_task where task_id=tid;
 select x.* into v from population_top3000_202608_202609_v1.pipeline_partition p join population_top3000_202608_202609_v1.pipeline_validation x on x.validation_id=p.last_validation_id where p.family_id=t.family_id and p.partition_key=t.partition_key;
 if not found then return jsonb_build_object('state','BLOCKED','blocker_code','VALIDATION_REQUIRED','resumption_condition',jsonb_build_object('event','PARTITION_VALIDATION_COMMITTED'));end if;
 m:=population_top3000_202608_202609_v1.pipeline_measure_partition_v1(t.family_id,t.partition_key);
 if m->>'state'<>'MEASURED' or m->>'expected_manifest_sha256' is distinct from v.expected_manifest_sha256 or m->>'observed_manifest_sha256' is distinct from v.observed_manifest_sha256 then
 return jsonb_build_object('state','BLOCKED','blocker_code','INPUT_CHANGED_REVERIFY_NEW_REVISION','resumption_condition',jsonb_build_object('event','NEW_INPUT_REVISION_VALIDATION_ENQUEUED'));end if;
 for item in select * from (values
 ('MISSING_SOURCE_UNITS',v.missing_units,'Acquire missing expected source keys through the bound family acquisition adapter.'),
 ('MISSING_REQUIRED_FIELDS',v.missing_required_fields,'Repair exact absent required fields from source spans; never fill fabricated values.'),
 ('UNAVAILABLE_HISTORY',v.unavailable_fields,'Provide a genuine historical source/version or documented publisher missingness.'),
 ('CONFLICTING_FIELDS',v.conflicting_fields,'Resolve source conflict with evidence and preserve both source versions.'),
 ('QUARANTINED_FIELDS',v.quarantined_fields,'Apply diagnosed source-backed correction and independently reverify.'),
 ('UNEXPECTED_UNITS',v.unexpected_units,'Reconcile source/index membership; never silently drop source rows.'),
 ('STRUCTURAL_FAILURES',v.structural_failures,'Rebuild only mismatched normalized rows from retained immutable raw evidence.'),
 ('MEMBERSHIP_FAILURES',v.membership_failures,'Resolve evidenced dated company/security mapping.'),
 ('TEMPORAL_FAILURES',v.temporal_failures,'Correct actual source time semantics; never synthesize receipt timestamps.'),
 ('REQUIRED_INDEPENDENT_CHECKS',cardinality(v.required_checks_missing)::bigint,'Complete missing independent source, outlier and consumer checks bound to these manifests.'),
 ('DENOMINATOR_UNRESOLVED',case when v.result='DENOMINATOR_UNRESOLVED' then 1 else 0 end::bigint,'Freeze independently supported source expectations and required company universe.')
 ) x(code,units,resume) where units>0 loop
 insert into population_top3000_202608_202609_v1.pipeline_exception(family_id,partition_key,validation_id,code,affected_units,evidence,resumption_condition)
 values(t.family_id,t.partition_key,v.validation_id,item.code,item.units,jsonb_build_object('validation_id',v.validation_id,'expected_manifest_sha256',v.expected_manifest_sha256,'observed_manifest_sha256',v.observed_manifest_sha256,'required_checks_missing',v.required_checks_missing),jsonb_build_object('event','REVIEWED_REPAIR_SOURCE_OR_CODE_AVAILABLE','action',item.resume)) on conflict(validation_id,code) do nothing;
 get diagnostics n=row_count;
 end loop;
 select encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('code',code,'units',affected_units) order by code),'[]')::text,'UTF8')),'hex'),count(*) into out_hash,n from population_top3000_202608_202609_v1.pipeline_exception where validation_id=v.validation_id;
 return jsonb_build_object('state','COMPLETE','repair_outcome','NO_SAFE_AUTOMATIC_REPAIR','repair_applied',false,'unresolved_exceptions',n,'next_stage','PUBLISH','publication_classification','PROVISIONAL_SOURCE_EVIDENCE',
 'commit_receipt',jsonb_build_object('commit_key','repair-diagnosis:'||v.validation_id::text,'output_sha256',out_hash,'new_committed_units',n,'immutable_output_ids',jsonb_build_array(v.validation_id),'input_versions',t.input_versions));
end $function$

functions.sec_index_parse_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.sec_index_parse_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;src text;iv jsonb;s population_top3000_202608_202609_v1.sec_source_manifest_v1%rowtype;c population_top3000_202608_202609_v1.sec_source_chunk_v1%rowtype;data_n integer;target_n integer;bad_n integer;inserted_n integer;total_source bigint;total_target bigint;actual_target bigint;
begin
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 select payload->>'source_id',input_versions into src,iv from population_top3000_202608_202609_v1.pipeline_task where task_id=tid;
 select * into s from population_top3000_202608_202609_v1.sec_source_manifest_v1 where source_id=src;
 if s.source_id is distinct from 'SEC_Q3_2026_MASTER_INDEX' or s.source_kind<>'QUARTER_INDEX' or s.raw_state<>'COMPLETE_VERIFIED' then raise exception 'SEC_INDEX_RAW_NOT_VERIFIED';end if;
 select * into c from population_top3000_202608_202609_v1.sec_source_chunk_v1 where source_id=src and parse_state='PENDING' order by part_number for update skip locked limit 1;
 if not found then
  select sum(source_data_rows),sum(target_rows) into total_source,total_target from population_top3000_202608_202609_v1.sec_source_chunk_v1 where source_id=src and parse_state='PARSED';
  select count(*) into actual_target from population_top3000_202608_202609_v1.sec_filing_index_v1 where source_id=src;
  if total_source is distinct from 302400 or total_target is distinct from 207593 or actual_target is distinct from 207593 or exists(select 1 from population_top3000_202608_202609_v1.sec_source_chunk_v1 where source_id=src and parse_state<>'PARSED') then raise exception 'SEC_INDEX_EXACT_COUNT_RECONCILIATION_FAILED';end if;
  return jsonb_build_object('state','COMPLETE','commit_receipt',jsonb_build_object('commit_key','sec-index-complete:'||s.source_sha256,'input_versions',iv,'immutable_output_ids',jsonb_build_array(src||':normalized-index'),'output_sha256',s.source_sha256,'new_committed_units',0,'source_rows',total_source,'target_index_rows',actual_target,'selected_company_coverage',null,'publication_times_complete',false));
 end if;
 if c.first_source_line is null then raise exception 'SEC_INDEX_LINE_OFFSETS_MISSING';end if;
 with lines as(select line,ord,c.first_source_line+ord-1 line_number from regexp_split_to_table(c.raw_text,E'\n') with ordinality q(line,ord)),data as(select *,string_to_array(line,'|') f from lines where line ~ '^[0-9]+[|]')
 select count(*),count(*) filter(where array_length(f,1)<>5 or f[4] !~ '^2026-[0-9]{2}-[0-9]{2}$' or f[5] !~ '^edgar/data/[0-9]+/[0-9]{10}-[0-9]{2}-[0-9]{6}[.]txt$') into data_n,bad_n from data;
 if data_n>2000 or bad_n>0 or exists(select 1 from regexp_split_to_table(c.raw_text,E'\n') with ordinality q(line,ord) where line<>'' and line !~ '^[0-9]+[|]' and c.first_source_line+ord-1>20) then raise exception 'SEC_INDEX_SOURCE_LINE_INVALID';end if;
 with data as(select string_to_array(line,'|') f,c.first_source_line+ord-1 line_number from regexp_split_to_table(c.raw_text,E'\n') with ordinality q(line,ord) where line ~ '^[0-9]+[|]')
 insert into population_top3000_202608_202609_v1.sec_filing_index_v1(source_id,source_line_number,part_number,filing_cik,company_name,form,filing_date,accession_number,source_path_cik,source_filename)
 select src,line_number,c.part_number,lpad(f[1],10,'0'),f[2],f[3],f[4]::date,split_part(split_part(f[5],'/',4),'.',1),lpad(split_part(f[5],'/',3),10,'0'),f[5] from data where f[4]>='2026-08-01' and f[4]<'2026-10-01' on conflict do nothing;
 get diagnostics inserted_n=row_count;
 select count(*) into target_n from regexp_split_to_table(c.raw_text,E'\n') q(line) where line ~ '^[0-9]+[|]' and split_part(line,'|',4)>='2026-08-01' and split_part(line,'|',4)<'2026-10-01';
 if (select count(*) from population_top3000_202608_202609_v1.sec_filing_index_v1 where source_id=src and part_number=c.part_number)<>target_n then raise exception 'SEC_INDEX_PART_TARGET_COUNT_MISMATCH';end if;
 update population_top3000_202608_202609_v1.sec_source_chunk_v1 set parse_state='PARSED',source_data_rows=data_n,target_rows=target_n,parsed_at=clock_timestamp(),parse_receipt=jsonb_build_object('new_rows',inserted_n,'source_rows',data_n,'target_rows',target_n,'parser','sec-index-sql-v1') where source_id=src and part_number=c.part_number;
 return jsonb_build_object('state','CONTINUE','checkpoint',jsonb_build_object('source_id',src,'last_parsed_part',c.part_number),'commit_receipt',jsonb_build_object('commit_key','sec-index-part:'||src||':'||c.part_number||':'||c.chunk_sha256,'input_versions',iv,'immutable_output_ids',jsonb_build_array(src||':parsed-part:'||c.part_number),'output_sha256',c.chunk_sha256,'new_committed_units',inserted_n,'source_rows',data_n,'target_rows',target_n));
end $function$

functions.pipeline_deliver_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_deliver_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;pub uuid;d uuid:=gen_random_uuid();manifest jsonb;s text;cnt bigint;rejected bigint;
begin
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 select * into t from population_top3000_202608_202609_v1.pipeline_task where task_id=tid;
 select publication_id into pub from population_top3000_202608_202609_v1.pipeline_release_pointer where singleton;
 if pub is null then return jsonb_build_object('state','BLOCKED','blocker_code','PUBLICATION_REQUIRED','resumption_condition',jsonb_build_object('event','VALIDATED_RELEASE_POINTER_AVAILABLE'));end if;
 if not exists(select 1 from population_top3000_202608_202609_v1.pipeline_publication_member where publication_id=pub and family_id=t.family_id and partition_key=t.partition_key) then raise exception 'DELIVERY_PARTITION_NOT_PUBLISHED';end if;
 select count(*) into cnt from population_top3000_202608_202609_v1.population_source_evidence_current_v1 where family_id=t.family_id and partition_key=t.partition_key;
 select count(*) into rejected from population_top3000_202608_202609_v1.population_read_asof_v1('1900-01-01T00:00:00Z',false) where family_id=t.family_id and partition_key=t.partition_key;
 if rejected<>0 then raise exception 'CONSUMER_FUTURE_DATA_REJECTION_FAILED';end if;
 manifest:=jsonb_build_object('publication_id',pub,'source_evidence_rows_read',cnt,'consumer_future_rejection','PASS','serving_evidence_view','population_top3000_202608_202609_v1.population_source_evidence_current_v1',
 'consumer_function','population_top3000_202608_202609_v1.population_read_asof_v1','family_id',t.family_id,'partition_key',t.partition_key,'full_gate',population_top3000_202608_202609_v1.pipeline_full_gate_v1(),
 'artifact_export','PENDING_EXTERNAL_EXPORT','final_delivery',false,'required_artifacts',jsonb_build_array('24-family completion workbook','company and instrument manifests','dictionary and provenance','verification and exception evidence','D06 preservation appendix','actual and forecast cost report'));
 s:=encode(sha256(convert_to(manifest::text,'UTF8')),'hex');
 insert into population_top3000_202608_202609_v1.pipeline_delivery(delivery_id,publication_id,manifest,manifest_sha256) values(d,pub,manifest,s);
 -- A manifest is a durable export request, never a false artifact-export receipt.
 return jsonb_build_object('state','COMPLETE','delivery_id',d,'artifact_state','PENDING_EXPORT','final_delivery',false,
 'commit_receipt',jsonb_build_object('commit_key','delivery-manifest:'||d::text,'output_sha256',s,'new_committed_units',1,'immutable_output_ids',jsonb_build_array(d),'input_versions',t.input_versions));
end $function$

functions.pipeline_enqueue_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_enqueue_v1(p_family text, p_stage text, p_partition text, p_payload jsonb, p_input_versions jsonb, p_dependency uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;k text;
begin
if not exists(select 1 from population_top3000_202608_202609_v1.catalog_family_contract where family_id=p_family) and p_family<>'MISSION' then raise exception 'OUT_OF_SCOPE_FAMILY';end if;
if p_stage not in('PLAN','ACQUIRE','NORMALIZE','DERIVE','VALIDATE','REPAIR','PUBLISH','DELIVER') or p_stage is null or p_partition is null or p_input_versions is null or jsonb_typeof(p_input_versions)<>'object' then raise exception 'TASK_SCOPE_INVALID';end if;
k:=p_family||':'||p_stage||':'||p_partition||':'||encode(sha256(convert_to(p_input_versions::text,'UTF8')),'hex');
insert into population_top3000_202608_202609_v1.pipeline_task(operation_key,family_id,stage,partition_key,payload,input_versions)values(k,p_family,p_stage,p_partition,p_payload,p_input_versions)on conflict(operation_key)do nothing;
select task_id into tid from population_top3000_202608_202609_v1.pipeline_task where operation_key=k;
if p_dependency is not null then insert into population_top3000_202608_202609_v1.pipeline_dependency(task_id,prerequisite_task_id)values(tid,p_dependency)on conflict do nothing;end if;
return tid;
end $function$

functions.pipeline_publish_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_publish_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;v population_top3000_202608_202609_v1.pipeline_validation%rowtype;
 p population_top3000_202608_202609_v1.pipeline_partition%rowtype;b jsonb;m jsonb;manifest jsonb;class text;pub uuid:=gen_random_uuid();prev uuid;n bigint;s text;gate jsonb;
begin
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 select * into t from population_top3000_202608_202609_v1.pipeline_task where task_id=tid;
 select * into p from population_top3000_202608_202609_v1.pipeline_partition where family_id=t.family_id and partition_key=t.partition_key for update;
 select * into v from population_top3000_202608_202609_v1.pipeline_validation where validation_id=p.last_validation_id;
 if not found then return jsonb_build_object('state','BLOCKED','blocker_code','PERSISTED_VALIDATION_REQUIRED','resumption_condition',jsonb_build_object('event','PARTITION_VALIDATION_COMMITTED'));end if;
 if v.input_versions is distinct from t.input_versions then raise exception 'PUBLICATION_INPUT_REVISION_MISMATCH';end if;
 m:=population_top3000_202608_202609_v1.pipeline_measure_partition_v1(t.family_id,t.partition_key);
 if m->>'state'<>'MEASURED' or m->>'expected_manifest_sha256' is distinct from v.expected_manifest_sha256 or m->>'observed_manifest_sha256' is distinct from v.observed_manifest_sha256 then raise exception 'PUBLICATION_SOURCE_CHANGED_SINCE_VALIDATION';end if;
 if v.duplicate_observed_units>0 then return jsonb_build_object('state','BLOCKED','blocker_code','DUPLICATE_UNITS_REQUIRE_REPAIR','resumption_condition',jsonb_build_object('event','UNIQUENESS_REPAIR_VERIFIED'));end if;
 gate:=population_top3000_202608_202609_v1.pipeline_full_gate_v1();
 -- A single partition publication cannot certify the full mission. Final aggregation must be explicit.
 class:=case when v.result='PASS' then 'PARTIAL_EVIDENCE_LIMITED' else 'PROVISIONAL_SOURCE_EVIDENCE' end;
 manifest:=jsonb_build_object('scope_sha256','8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd','family_id',t.family_id,'partition_key',t.partition_key,'validation_id',v.validation_id,
 'validation_result',v.result,'expected_manifest_sha256',v.expected_manifest_sha256,'observed_manifest_sha256',v.observed_manifest_sha256,'source_completeness',v.evidence,
 'strict_receipt_fields',v.strict_receipt_fields,'classification',class,'full_mission_gate',gate,'consumer_policy','Only PASS partition records, explicit availability <= requested as_of, no quarantined/conflicting/unavailable fields.');
 s:=encode(sha256(convert_to(manifest::text,'UTF8')),'hex');
 select publication_id into prev from population_top3000_202608_202609_v1.pipeline_release_pointer where singleton for update;
 insert into population_top3000_202608_202609_v1.pipeline_publication(publication_id,classification,company_manifest_sha256,instrument_manifest_sha256,manifest,manifest_sha256,previous_publication_id)
 select pub,class,company_manifest_sha256,instrument_manifest_sha256,manifest,s,prev from population_top3000_202608_202609_v1.pipeline_universe where singleton;
 insert into population_top3000_202608_202609_v1.pipeline_publication_member(publication_id,family_id,partition_key,validation_id,expected_manifest_sha256,observed_manifest_sha256,snapshot_publication_id)
 values(pub,t.family_id,t.partition_key,v.validation_id,v.expected_manifest_sha256,v.observed_manifest_sha256,pub);
 -- Copy only immutable snapshot REFERENCES, avoiding quadratic payload copies per release.
 if prev is not null then
  insert into population_top3000_202608_202609_v1.pipeline_publication_member(publication_id,family_id,partition_key,validation_id,expected_manifest_sha256,observed_manifest_sha256,snapshot_publication_id)
  select pub,family_id,partition_key,validation_id,expected_manifest_sha256,observed_manifest_sha256,snapshot_publication_id from population_top3000_202608_202609_v1.pipeline_publication_member where publication_id=prev and (family_id,partition_key)<>(t.family_id,t.partition_key);
 end if;
 b:=population_top3000_202608_202609_v1.pipeline_bound_relations_v1(t.family_id);
 execute format('insert into population_top3000_202608_202609_v1.pipeline_published_observation select $1,family_id,partition_key,unit_key,$2,$3,to_jsonb(x),encode(sha256(convert_to(to_jsonb(x)::text,''UTF8'')),''hex'') from %s x where release_id=''top3000_companies_202608_202609_v1'' and family_id=$4 and partition_key=$5',b->>'observed') using pub,v.validation_id,v.result,t.family_id,t.partition_key;
 get diagnostics n=row_count;
 if n<>v.received_units then raise exception 'PUBLICATION_SNAPSHOT_COUNT_MISMATCH';end if;
 if exists(select 1 from population_top3000_202608_202609_v1.pipeline_published_observation where publication_id=pub and snapshot_sha256<>encode(sha256(convert_to(observation::text,'UTF8')),'hex')) then raise exception 'PUBLICATION_SNAPSHOT_HASH_MISMATCH';end if;
 update population_top3000_202608_202609_v1.pipeline_release_pointer set publication_id=pub,updated_at=clock_timestamp() where singleton;
 return jsonb_build_object('state','COMPLETE','publication_id',pub,'publication_classification',class,'next_stage','DELIVER',
 'commit_receipt',jsonb_build_object('commit_key','publication:'||pub::text,'output_sha256',s,'new_committed_units',n,'immutable_output_ids',jsonb_build_array(pub),'input_versions',t.input_versions));
end $function$

functions.company_reconcile_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.company_reconcile_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;
 v jsonb;vsha text;n bigint:=0;m bigint:=0;src population_top3000_202608_202609_v1.source_document%rowtype;
 doc jsonb;rec jsonb;cik text;g text;request record;next_id uuid;selected integer:=0;
begin
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 select * into t from population_top3000_202608_202609_v1.pipeline_task where task_id=tid;
 if t.family_id<>'REF01' or t.stage<>'NORMALIZE' then raise exception 'COMPANY_ADAPTER_SCOPE_MISMATCH';end if;
 if t.payload->>'kind'='SEC_SUBMISSIONS' then
  cik:=t.payload->>'cik';g:='CIK:'||cik;
  if cik!~'^[0-9]{10}$' then raise exception 'CIK_INVALID';end if;
  select * into src from population_top3000_202608_202609_v1.source_document where source_id=t.payload->>'source_id';
  if not found or src.content_text is null or encode(sha256(convert_to(src.content_text,'UTF8')),'hex') is distinct from src.source_sha256 then raise exception 'ISSUER_RAW_SOURCE_MISSING_OR_HASH_MISMATCH';end if;
  doc:=src.content_text::jsonb;
  if lpad(doc->>'cik',10,'0') is distinct from cik then raise exception 'SEC_ISSUER_CIK_MISMATCH';end if;
  update population_top3000_202608_202609_v1.company_group_v1 set identity_evidence=identity_evidence||jsonb_build_object(
   'sec_source_id',src.source_id,'sec_source_sha256',src.source_sha256,'sec_cik_matches',true,
   'current_sec_name',doc->>'name','current_sec_tickers',doc->'tickers','historical_listing_proven_by_current_tickers',false),
   reconciliation_state='ISSUER_SOURCE_CORROBORATED_HISTORY_PENDING',updated_at=clock_timestamp() where group_key=g;
  -- Preserve latest annual and latest interim candidates accepted by the rank instant, each independently dated.
  with f as(select (doc#>'{filings,recent,accessionNumber}')->>i accession,(doc#>'{filings,recent,form}')->>i form,
   nullif((doc#>'{filings,recent,filingDate}')->>i,'')::date filing_date,
   nullif((doc#>'{filings,recent,acceptanceDateTime}')->>i,'')::timestamptz accepted_at,
   (doc#>'{filings,recent,primaryDocument}')->>i primary_document
   from generate_series(0,jsonb_array_length(coalesce(doc#>'{filings,recent,accessionNumber}','[]'))-1)i), ranked as(
   select *,row_number() over(partition by case when form in('10-K','20-F','40-F')then 'ANNUAL' else 'INTERIM' end order by accepted_at desc,accession) rn
   from f where form in('10-K','10-Q','20-F','40-F','6-K') and accepted_at<='2026-08-03T20:00Z' and primary_document is not null)
  insert into population_top3000_202608_202609_v1.company_filing_candidate_v1(group_key,accession,cik,form,filing_date,accepted_at,primary_document,document_url,source_id,source_sha256)
  select g,accession,cik,form,filing_date,accepted_at,primary_document,
   'https://www.sec.gov/Archives/edgar/data/'||cik::bigint||'/'||replace(accession,'-','')||'/'||primary_document,src.source_id,src.source_sha256 from ranked where rn=1
  on conflict do nothing;
  get diagnostics n=row_count;
  update population_top3000_202608_202609_v1.company_source_request_v1 set state='NORMALIZED',source_sha256=src.source_sha256,
   result=jsonb_build_object('issuer_cik_corroborated',true,'historical_tickers_certified',false,'filing_candidates',n),updated_at=clock_timestamp() where source_id=src.source_id;
  for request in select * from population_top3000_202608_202609_v1.company_filing_candidate_v1 where group_key=g loop
   -- Document work is a real queued source task; parsing later must not treat current names as historical proof.
   next_id:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF01','ACQUIRE','document:'||request.accession,
    jsonb_build_object('kind','SEC_DOCUMENT','url',request.document_url,'source_id','company:sec-document:'||request.accession,'group_key',g,'provisional',true),
    jsonb_build_object('submission_sha256',src.source_sha256,'accession',request.accession),tid);
   selected:=selected+1;
  end loop;
  v:=jsonb_build_object('source_id',src.source_id,'sha256',src.source_sha256,'issuer_cik_corroborated',true,'filing_candidates',n,'document_tasks',selected,'company_universe_frozen',false);
 elsif t.payload->>'kind'='SEC_DOCUMENT' then
  select * into src from population_top3000_202608_202609_v1.source_document where source_id=t.payload->>'source_id';
  if not found or src.content_text is null or encode(sha256(convert_to(src.content_text,'UTF8')),'hex') is distinct from src.source_sha256 then raise exception 'CLASS_DOCUMENT_MISSING_OR_HASH_MISMATCH';end if;
  if t.input_versions->>'cover_extractor_sha256' is distinct from encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.company_extract_cover_v1(text,text)'::regprocedure),'UTF8')),'hex') then raise exception 'COVER_EXTRACTOR_VERSION_REQUIRED';end if;
  rec:=population_top3000_202608_202609_v1.company_extract_cover_v1(src.source_id,t.payload->>'group_key');
  insert into population_top3000_202608_202609_v1.company_exception_v1(exception_key,group_key,code,priority,evidence,resumption_condition)
  values('document-parse:'||src.source_id,t.payload->>'group_key','CLASS_DOCUMENT_EXTRACTION_REQUIRED',10,
    jsonb_build_object('source_id',src.source_id,'source_sha256',src.source_sha256,'content_bytes',src.content_bytes,'cover_extraction',rec),
    '{"event":"source_span_bound_class_and_shares_extraction_verified","required":"Extract cover equity classes and dated outstanding counts; reconcile class/ADR/FX economics and listing intervals."}') on conflict do nothing;
  get diagnostics n=row_count;
  n:=n+coalesce((rec->>'cover_facts')::integer,0);
  v:=jsonb_build_object('source_id',src.source_id,'sha256',src.source_sha256,'retained_document_verified',true,'cover_extraction',rec,'historical_class_reconciliation_complete',false);
 else
  v:=population_top3000_202608_202609_v1.company_verify_overviews_v1();
  if v->>'passed' is distinct from 'true' then raise exception 'OVERVIEW_INDEPENDENT_RECONCILIATION_FAILED: %',v;end if;
  vsha:=v->>'source_manifest_sha256';
  insert into population_top3000_202608_202609_v1.company_verification_v1(verifier_version,result) values('company-overview-independent-v1',v);
  insert into population_top3000_202608_202609_v1.company_candidate_v1(ticker,census_job_id,census_ordinal,census_sha256,overview_job_id,overview_sha256,
    source_type,source_name,primary_exchange,cik_candidate,composite_figi,share_class_figi,group_key,classification,classification_conflict,
    vendor_cap_screen,vendor_class_shares,vendor_equivalent_shares,input_sha256)
  select r.ticker,r.page_job_id,r.ordinal,a.sha256,o.source_job_id,b.sha256,r.security_type,
    coalesce(o.raw_record->>'name',r.raw_record->>'name'),coalesce(o.raw_record->>'primary_exchange',r.raw_record->>'primary_exchange'),
    coalesce(nullif(o.raw_record->>'cik',''),nullif(r.raw_record->>'cik','')),
    coalesce(o.raw_record->>'composite_figi',r.raw_record->>'composite_figi'),coalesce(o.raw_record->>'share_class_figi',r.raw_record->>'share_class_figi'),
    coalesce('CIK:'||coalesce(nullif(o.raw_record->>'cik',''),nullif(r.raw_record->>'cik','')),'TICKER:'||r.ticker),
    case when r.security_type in('CS','ADRC','OS','NYRS','GDR','OTHER')then 'POTENTIAL_COMMON'
     when r.security_type in('PFD','WARRANT','RIGHT','BOND','ETF','ETN','ETV','SP','ADRP','ADRW','ADRR','FUND','BASKET','UNIT','LT','AGEN','EQLK','ETS')then 'TYPE_EXCLUSION_CANDIDATE' else 'UNCLASSIFIED' end,
    coalesce(r.security_type in('CS','ADRC','OS','NYRS','GDR','OTHER') and coalesce(o.raw_record->>'name',r.raw_record->>'name','')~*'(preferred|\mpfd\M|\mnotes\M|\mbonds\M|debenture|\mrights\M|\munits\M|\mfund\M|bitcoin trust)',false),
    nullif(o.raw_record->>'market_cap','')::numeric,nullif(o.raw_record->>'share_class_shares_outstanding','')::numeric,
    nullif(o.raw_record->>'weighted_shares_outstanding','')::numeric,
    encode(sha256(convert_to(a.sha256||':'||r.ordinal||':'||coalesce(b.sha256,'NO_OVERVIEW'),'UTF8')),'hex')
  from population_top3000_202608_202609_v1.reference_row r
  join population_top3000_202608_202609_v1.acquisition_raw a on a.job_id=r.page_job_id
  left join population_top3000_202608_202609_v1.ticker_overview o on o.ticker=r.ticker and o.snapshot_date='2026-08-03'
  left join population_top3000_202608_202609_v1.acquisition_raw b on b.job_id=o.source_job_id on conflict(ticker)do nothing;
  get diagnostics n=row_count;
  insert into population_top3000_202608_202609_v1.company_group_v1(group_key,cik_candidate,candidate_tickers,line_count,vendor_cap_screen_min,vendor_cap_screen_max,
   adr_lines,classification_conflicts,missing_cap_lines,input_sha256)
  select group_key,max(cik_candidate),array_agg(ticker order by ticker),count(*),min(vendor_cap_screen),max(vendor_cap_screen),
   count(*)filter(where source_type in('ADRC','GDR')),count(*)filter(where classification_conflict),count(*)filter(where vendor_cap_screen is null),
   encode(sha256(convert_to(string_agg(input_sha256,E'\n' order by ticker),'UTF8')),'hex')
  from population_top3000_202608_202609_v1.company_candidate_v1 where classification<>'TYPE_EXCLUSION_CANDIDATE' group by group_key on conflict(group_key)do nothing;
  get diagnostics m=row_count;n:=n+m;
  with ranked as(select group_key,row_number()over(order by vendor_cap_screen_max desc nulls last,group_key) r from population_top3000_202608_202609_v1.company_group_v1)
  update population_top3000_202608_202609_v1.company_group_v1 g set screening_rank=r.r from ranked r where r.group_key=g.group_key;
  insert into population_top3000_202608_202609_v1.company_exception_v1(exception_key,group_key,ticker,code,priority,evidence,resumption_condition)
  select ticker||':'||code,group_key,ticker,code,priority,jsonb_build_object('source_job_id',overview_job_id,'source_sha256',overview_sha256,'vendor_type',source_type,'vendor_name',source_name),
   jsonb_build_object('event','independent_dated_source_evidence_committed','required_action',action)
  from population_top3000_202608_202609_v1.company_candidate_v1 c
  cross join lateral(values
   ('IDENTITY_MISSING_CIK',5,c.cik_candidate is null,'Obtain issuer/exchange/bank-regulator identity evidence; CIK absence does not exclude a company.'),
   ('TYPE_NAME_CONFLICT',5,c.classification_conflict,'Resolve common-versus-preferred/debt/fund/units using an issuer or exchange record. Regex is only a conflict flag.'),
   ('MARKET_CAP_MISSING',10,c.vendor_cap_screen is null,'Acquire shares/price or verified company-level cap; missing cap is never zero.'),
   ('ADR_GLOBAL_EQUITY',15,c.source_type in('ADRC','GDR'),'Establish dated global common classes, ADR ratio, quoted units and FX; do not add receipt supply twice.')
  )e(code,priority,applies,action) where c.classification<>'TYPE_EXCLUSION_CANDIDATE' and applies on conflict(exception_key)do nothing;
  get diagnostics m=row_count;n:=n+m;
  insert into population_top3000_202608_202609_v1.company_exception_v1(exception_key,group_key,code,priority,evidence,resumption_condition)
  select group_key||':CAP_AND_IDENTITY',group_key,'COMPANY_CAP_AND_IDENTITY_RECONCILIATION',case when screening_rank between 2850 and 3150 then 1 when classification_conflicts>0 or missing_cap_lines>0 then 5 when line_count>1 then 10 else 30 end,
   jsonb_build_object('tickers',candidate_tickers,'cik',cik_candidate,'line_count',line_count,'vendor_cap_min',vendor_cap_screen_min,'vendor_cap_max',vendor_cap_screen_max,'screening_rank_only',screening_rank,'source_hash',input_sha256),
   '{"event":"verified_company_resolution_committed","required_action":"Resolve historical issuer/eligible common-class inventory and total company cap. Screening vendor maxima are not certified values or mathematical bounds."}'
  from population_top3000_202608_202609_v1.company_group_v1 on conflict(exception_key)do nothing;
  get diagnostics m=row_count;n:=n+m;
  insert into population_top3000_202608_202609_v1.company_source_request_v1(request_key,group_key,kind,source_id,payload,priority)
  select 'issuer:'||cik_candidate,group_key,'SEC_SUBMISSIONS','company:sec-submissions:'||cik_candidate,
   jsonb_build_object('kind','SEC_SUBMISSIONS','cik',cik_candidate,'source_id','company:sec-submissions:'||cik_candidate,'provisional',true),
   case when screening_rank between 2950 and 3050 then 1 when classification_conflicts>0 or missing_cap_lines>0 then 5 when line_count>1 then 10 when adr_lines>0 then 15 else 30 end
  from population_top3000_202608_202609_v1.company_group_v1 where cik_candidate~'^[0-9]{10}$' on conflict(request_key)do nothing;
  -- Initial admission is a measured 200-issuer batch, with remaining scope retained in the source queue.
  for request in select * from population_top3000_202608_202609_v1.company_source_request_v1 where state='PENDING_ADMISSION' and exists(select 1 from population_top3000_202608_202609_v1.pipeline_adapter where family_id='REF01' and stage='ACQUIRE' and enabled) order by priority,request_key limit 200 loop
   next_id:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('REF01','ACQUIRE',request.request_key,request.payload,
    jsonb_build_object('census_overview_manifest',vsha,'source_request',request.request_key),tid);
   update population_top3000_202608_202609_v1.company_source_request_v1 set state='QUEUED',task_id=next_id,updated_at=clock_timestamp() where request_key=request.request_key;
   selected:=selected+1;
  end loop;
  v:=v||jsonb_build_object('candidate_rows',(select count(*)from population_top3000_202608_202609_v1.company_candidate_v1),
    'provisional_groups',(select count(*)from population_top3000_202608_202609_v1.company_group_v1),'new_units',n,'source_tasks_queued',selected,
    'remaining_source_requests',(select count(*)from population_top3000_202608_202609_v1.company_source_request_v1 where state='PENDING_ADMISSION'),
    'source_batch_limit_is_not_population_exclusion',true,'company_universe_frozen',false);
 end if;
 return population_top3000_202608_202609_v1.pipeline_finish_v1(p_attempt,p_token,jsonb_build_object('state','COMPLETE','commit_receipt',
  jsonb_build_object('commit_key','company-normalize:'||t.operation_key,'output_sha256',encode(sha256(convert_to(v::text,'UTF8')),'hex'),
   'new_committed_units',n+1,'immutable_output_ids',jsonb_build_array(t.partition_key),'input_versions',t.input_versions,'evidence',v)));
end $function$

functions.pipeline_validate_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_validate_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;t population_top3000_202608_202609_v1.pipeline_task%rowtype;p population_top3000_202608_202609_v1.pipeline_partition%rowtype;
 b population_top3000_202608_202609_v1.pipeline_family_binding%rowtype;m jsonb;v uuid:=gen_random_uuid();missing_checks text[];outcome text;universe_missing boolean;
begin
 tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 select * into t from population_top3000_202608_202609_v1.pipeline_task where task_id=tid;
 select * into p from population_top3000_202608_202609_v1.pipeline_partition where family_id=t.family_id and partition_key=t.partition_key for update;
 if not found then return jsonb_build_object('state','BLOCKED','blocker_code','PARTITION_DENOMINATOR_NOT_DEFINED','resumption_condition',jsonb_build_object('event','SOURCE_EXPECTATION_PARTITION_CREATED','family_id',t.family_id,'partition_key',t.partition_key));end if;
 if p.immutable_input_versions is distinct from t.input_versions then raise exception 'PARTITION_INPUT_REVISION_MISMATCH';end if;
 select * into b from population_top3000_202608_202609_v1.pipeline_family_binding where family_id=t.family_id;
 m:=population_top3000_202608_202609_v1.pipeline_measure_partition_v1(t.family_id,t.partition_key);
 if m->>'state'<>'MEASURED' then return jsonb_build_object('state','BLOCKED','blocker_code',m->>'state','resumption_condition',jsonb_build_object('event','REVIEWED_FAMILY_BINDING_AVAILABLE','family_id',t.family_id));end if;
 select coalesce(array_agg(code order by code),'{}'::text[]) into missing_checks from unnest(b.required_check_codes) code
 where not exists(select 1 from population_top3000_202608_202609_v1.pipeline_quality_evidence e where e.family_id=t.family_id and e.partition_key=t.partition_key and e.check_code=code
 and e.result in('PASS','NOT_APPLICABLE') and e.independent_of_producer and e.verifier_revision<>p.producer_revision and e.discrepancy_count=0 and e.input_versions=t.input_versions
 and e.evidence->>'expected_manifest_sha256'=m->>'expected_manifest_sha256' and e.evidence->>'observed_manifest_sha256'=m->>'observed_manifest_sha256');
 universe_missing:=b.requires_company_universe and not exists(select 1 from population_top3000_202608_202609_v1.pipeline_universe where singleton and status='FROZEN' and company_count=3000 and unresolved_cutoff_cases=0 and unresolved_instrument_cases=0);
 outcome:=case when (m->>'structural_failures')::bigint+(m->>'membership_failures')::bigint+(m->>'temporal_failures')::bigint+(m->>'duplicate_expected_units')::bigint+(m->>'duplicate_observed_units')::bigint>0 then 'FAIL'
 when p.denominator_state<>'FROZEN' or p.denominator_sha256 is distinct from m->>'expected_manifest_sha256' or universe_missing then 'DENOMINATOR_UNRESOLVED'
 when (m->>'missing_units')::bigint+(m->>'missing_required_fields')::bigint+(m->>'unexpected_units')::bigint+(m->>'unavailable_fields')::bigint+(m->>'conflicting_fields')::bigint+(m->>'quarantined_fields')::bigint>0 or cardinality(missing_checks)>0 then 'REQUIRED_GAPS'
 when (m->>'expected_units')::bigint=0 and not coalesce((p.denominator_evidence->>'source_index_verified_empty')::boolean,false) then 'DENOMINATOR_UNRESOLVED' else 'PASS' end;
 insert into population_top3000_202608_202609_v1.pipeline_validation(validation_id,family_id,partition_key,validator_revision,input_versions,expected_units,received_units,required_fields,
 verified_value_fields,not_applicable_fields,published_missing_fields,unavailable_fields,conflicting_fields,quarantined_fields,missing_units,missing_required_fields,unexpected_units,duplicate_expected_units,duplicate_observed_units,structural_failures,membership_failures,temporal_failures,strict_receipt_fields,expected_manifest_sha256,observed_manifest_sha256,required_checks_missing,result,evidence)
 values(v,t.family_id,t.partition_key,'generic-independent-readback-v1',t.input_versions,(m->>'expected_units')::bigint,(m->>'received_units')::bigint,(m->>'required_fields')::bigint,
 (m->>'verified_value_fields')::bigint,(m->>'not_applicable_fields')::bigint,(m->>'published_missing_fields')::bigint,(m->>'unavailable_fields')::bigint,(m->>'conflicting_fields')::bigint,(m->>'quarantined_fields')::bigint,
 (m->>'missing_units')::bigint,(m->>'missing_required_fields')::bigint,(m->>'unexpected_units')::bigint,(m->>'duplicate_expected_units')::bigint,(m->>'duplicate_observed_units')::bigint,(m->>'structural_failures')::bigint,(m->>'membership_failures')::bigint,(m->>'temporal_failures')::bigint,(m->>'strict_receipt_fields')::bigint,
 m->>'expected_manifest_sha256',m->>'observed_manifest_sha256',missing_checks,outcome,m||jsonb_build_object('denominator_state',p.denominator_state,'company_universe_missing',universe_missing,'value_count_is_structural_not_independent_source_accuracy',true));
 update population_top3000_202608_202609_v1.pipeline_partition set last_validation_id=v,expected_units=(m->>'expected_units')::bigint,received_units=(m->>'received_units')::bigint,
 verified_value_fields=case when outcome='PASS' then (m->>'verified_value_fields')::bigint else 0 end,not_applicable_fields=(m->>'not_applicable_fields')::bigint,published_missing_fields=(m->>'published_missing_fields')::bigint,
 unavailable_fields=(m->>'unavailable_fields')::bigint,conflicting_fields=(m->>'conflicting_fields')::bigint,quarantined_fields=(m->>'quarantined_fields')::bigint,missing_units=(m->>'missing_units')::bigint,
 missing_required_fields=(m->>'missing_required_fields')::bigint,unexpected_units=(m->>'unexpected_units')::bigint,strict_receipt_fields=(m->>'strict_receipt_fields')::bigint,publication_eligible=outcome='PASS'
 where family_id=t.family_id and partition_key=t.partition_key;
 if outcome='PASS' then
  update population_top3000_202608_202609_v1.pipeline_exception set resolved_at=clock_timestamp()
  where family_id=t.family_id and partition_key=t.partition_key and resolved_at is null;
 end if;
 return jsonb_build_object('state','COMPLETE','quality_result',outcome,'validation_id',v,'next_stage',case when outcome='PASS' then 'PUBLISH' else 'REPAIR' end,
 'commit_receipt',jsonb_build_object('commit_key','validation:'||v::text,'output_sha256',encode(sha256(convert_to(m::text,'UTF8')),'hex'),'new_committed_units',1,'immutable_output_ids',jsonb_build_array(v),'input_versions',t.input_versions));
end $function$

functions.sec_cached_acquire_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.sec_cached_acquire_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
