 if not exists(select 1 from population_top3000_202608_202609_v1.catalog_family_contract where family_id=p_family) then raise exception 'OUT_OF_SCOPE_FAMILY';end if;
 if p_partition is null or jsonb_typeof(p_input_versions) is distinct from 'object' then raise exception 'TASK_SCOPE_INVALID';end if;
 k:=p_family||':'||p_stage||':'||p_partition||':'||encode(sha256(convert_to(p_input_versions::text,'UTF8')),'hex')||':quality-round:'||p_round::text;
 insert into population_top3000_202608_202609_v1.pipeline_task(operation_key,family_id,stage,partition_key,payload,input_versions,repair_round)
 values(k,p_family,p_stage,p_partition,p_payload,p_input_versions,p_round)on conflict(operation_key)do nothing;
 select task_id into tid from population_top3000_202608_202609_v1.pipeline_task where operation_key=k;
 if p_dependency is not null then insert into population_top3000_202608_202609_v1.pipeline_dependency(task_id,prerequisite_task_id)values(tid,p_dependency)on conflict do nothing;end if;
 return tid;
end $function$

functions.pipeline_record_commit_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_record_commit_v1(p_attempt uuid, p_token text, p_receipt jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;k text;s text;n bigint;old_s text;
begin
tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
k:=p_receipt->>'commit_key';s:=p_receipt->>'output_sha256';
if k is null or length(k)>1024 or s is null or s!~'^[0-9a-f]{64}$' or jsonb_typeof(p_receipt->'new_committed_units') is distinct from 'number' or not(p_receipt ? 'immutable_output_ids') or not(p_receipt ? 'input_versions') then raise exception 'COMMIT_RECEIPT_INVALID';end if;
n:=(p_receipt->>'new_committed_units')::bigint;if n<0 then raise exception 'COMMIT_UNITS_INVALID';end if;
if (select input_versions from population_top3000_202608_202609_v1.pipeline_task where task_id=tid) is distinct from p_receipt->'input_versions' then raise exception 'COMMIT_INPUT_VERSION_MISMATCH';end if;
select output_sha256 into old_s from population_top3000_202608_202609_v1.pipeline_commit where commit_key=k;
if found then if old_s is distinct from s then raise exception 'IMMUTABLE_COMMIT_CONFLICT';end if;return false;end if;
insert into population_top3000_202608_202609_v1.pipeline_commit(attempt_id,task_id,commit_key,output_sha256,receipt,new_committed_units) values(p_attempt,tid,k,s,p_receipt,n);
update population_top3000_202608_202609_v1.pipeline_task set useful_committed_units=useful_committed_units+n,last_useful_progress_at=case when n>0 then clock_timestamp() else last_useful_progress_at end where task_id=tid;
if n>0 then
 update population_top3000_202608_202609_v1.pipeline_control set last_useful_progress_at=clock_timestamp() where singleton;
 update population_top3000_202608_202609_v1.acquisition_control set last_useful_progress_at=clock_timestamp(),updated_at=clock_timestamp() where singleton;
end if;
return true;
end $function$

functions.pipeline_assert_attempt_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt uuid, p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare c population_top3000_202608_202609_v1.acquisition_control%rowtype;
p population_top3000_202608_202609_v1.pipeline_control%rowtype;
a population_top3000_202608_202609_v1.pipeline_attempt%rowtype;
t population_top3000_202608_202609_v1.pipeline_task%rowtype;
b population_top3000_202608_202609_v1.pipeline_adapter%rowtype;
bound_hash text;
begin
select * into c from population_top3000_202608_202609_v1.acquisition_control where singleton for update;
if not found then raise exception 'CONTROL_MISSING';end if;
select * into p from population_top3000_202608_202609_v1.pipeline_control where singleton for update;
if not found then raise exception 'PIPELINE_CONTROL_MISSING';end if;
if c.owner_id is distinct from p.expected_owner_id or c.owner_fence is distinct from p.expected_owner_fence or c.stop_generation is distinct from p.expected_stop_generation then raise exception 'CONTROLLER_OWNERSHIP_CHANGED';end if;
if c.scope_sha256 is distinct from '8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd' or p.scope_sha256 is distinct from c.scope_sha256 then raise exception 'SCOPE_MISMATCH';end if;
if not c.enabled or c.stopped or c.hold_reason is not null or c.admitted_until<=clock_timestamp() or not p.enabled or not p.shared_scheduler_verified or (p.deadline is not null and p.deadline<=clock_timestamp()) then raise exception 'MISSION_HELD_OR_ADMISSION_EXPIRED';end if;
select * into a from population_top3000_202608_202609_v1.pipeline_attempt where attempt_id=p_attempt for update;
if not found or p_token is null or a.token_sha256 is distinct from encode(sha256(convert_to(p_token,'UTF8')),'hex') then raise exception 'ATTEMPT_AUTH_FAILED';end if;
select * into t from population_top3000_202608_202609_v1.pipeline_task where task_id=a.task_id for update;
if t.status is distinct from 'LEASED' or t.attempt_id is distinct from p_attempt or t.lease_until is null or t.lease_until<=clock_timestamp() then raise exception 'LEASE_LOST';end if;
if a.owner_fence is distinct from c.owner_fence or a.stop_generation is distinct from c.stop_generation or t.owner_fence is distinct from c.owner_fence or t.stop_generation is distinct from c.stop_generation then raise exception 'STALE_OWNER_OR_STOP';end if;
select * into b from population_top3000_202608_202609_v1.pipeline_adapter where family_id=t.family_id and stage=t.stage;
if not found or not b.enabled then raise exception 'ADAPTER_MISSING_OR_DISABLED';end if;
select encode(sha256(convert_to(pg_get_functiondef(b.function_oid),'UTF8')),'hex') into bound_hash;
if bound_hash is distinct from b.function_sha256 or a.adapter_sha256 is distinct from b.function_sha256 then raise exception 'ADAPTER_CODE_CHANGED';end if;
return t.task_id;
end $function$

functions.company_retained_acquire_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.company_retained_acquire_v1(p_attempt uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
 v_task_id uuid;
 v_task population_top3000_202608_202609_v1.pipeline_task%rowtype;
 v_control population_top3000_202608_202609_v1.acquisition_control%rowtype;
 v_manifest population_top3000_202608_202609_v1.sec_source_manifest_v1%rowtype;
 v_existing population_top3000_202608_202609_v1.source_document%rowtype;
 v_source_id text; v_expected_sha text; v_raw text; v_doc jsonb; v_chunks jsonb;
 v_parts bigint; v_bytes bigint; v_lo integer; v_hi integer; v_bad bigint;
 v_sha text; v_new_rows bigint:=0; v_kind text;
BEGIN
 v_task_id:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
 SELECT * INTO v_task FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id=v_task_id;
 IF v_task.family_id IS DISTINCT FROM 'REF01' OR v_task.stage IS DISTINCT FROM 'ACQUIRE' THEN RAISE EXCEPTION 'RETAINED_COMPANY_ADAPTER_SCOPE_MISMATCH';END IF;
 v_kind:=v_task.payload->>'kind';v_source_id:=v_task.payload->>'source_id';

 -- Existing NORMALIZE may enqueue document dependencies. They must never become network requests here.
 IF v_kind='SEC_DOCUMENT' THEN
  SELECT * INTO v_existing FROM population_top3000_202608_202609_v1.source_document WHERE source_id=v_source_id FOR SHARE;
  IF NOT FOUND OR v_existing.content_text IS NULL THEN
   RETURN jsonb_build_object('state','BLOCKED','blocker_code','RETAINED_COMPANY_DOCUMENT_REQUIRED',
    'resumption_condition',jsonb_build_object('source_id',v_source_id,'source_uri',v_task.payload->>'url','accession',v_task.input_versions->>'accession','group_key',v_task.payload->>'group_key',
     'required_action','Retain and independently verify this exact SEC filing document, then admit its immutable source SHA in a reviewed task. This adapter does not fetch missing documents.',
     'required_content','Exact original filing bytes with SHA-256, byte count and retrieval evidence','automatic_retry',false,'external_fetch_admitted',false));
  END IF;
  v_expected_sha:=v_task.input_versions->>'source_sha256';
  IF v_expected_sha IS NULL OR v_expected_sha IS DISTINCT FROM v_existing.source_sha256
   OR encode(sha256(convert_to(v_existing.content_text,'UTF8')),'hex') IS DISTINCT FROM v_existing.source_sha256
   OR v_existing.content_bytes IS DISTINCT FROM octet_length(v_existing.content_text)::bigint
   OR v_source_id IS DISTINCT FROM 'company:sec-document:'||(v_task.input_versions->>'accession')
   OR v_existing.source_uri IS DISTINCT FROM v_task.payload->>'url' THEN
   RETURN jsonb_build_object('state','BLOCKED','blocker_code','RETAINED_COMPANY_DOCUMENT_VERSION_REQUIRED',
    'resumption_condition',jsonb_build_object('source_id',v_source_id,'source_uri',v_task.payload->>'url','accession',v_task.input_versions->>'accession',
     'required_action','Reconcile the retained document hash, exact accession, byte count and URI; bind the approved source_sha256 in immutable task inputs.','automatic_retry',false,'external_fetch_admitted',false));
  END IF;
  RETURN jsonb_build_object('state','COMPLETE','commit_receipt',jsonb_build_object(
   'commit_key','company-retained-acquire:'||v_task.operation_key,'output_sha256',v_existing.source_sha256,
   'new_committed_units',0,'immutable_output_ids',jsonb_build_array(v_source_id),'input_versions',v_task.input_versions,
   'reused_bytes',v_existing.content_bytes,'no_provider_request',true,'original_historical_receipt_proven',false));
 END IF;

 -- This first admitted source is deliberately pinned to one verified retained bundle.
 IF v_kind IS DISTINCT FROM 'SEC_SUBMISSIONS' OR v_task.payload->>'retained_source_id' IS DISTINCT FROM 'NVDA_SUBMISSIONS'
  OR v_task.payload->>'cik' IS DISTINCT FROM '0001045810' OR v_source_id IS DISTINCT FROM 'company:sec-submissions:0001045810'
  OR v_task.payload->>'retained_only' IS DISTINCT FROM 'true'
  OR v_task.input_versions->>'source_sha256' IS DISTINCT FROM '682c49d59116ae49b317eb4adddf3ef9142dfd97f59c5d8e5a5acad7f9058ab4' THEN
  RETURN jsonb_build_object('state','BLOCKED','blocker_code','EXPLICIT_RETAINED_COMPANY_SOURCE_ADMISSION_REQUIRED',
   'resumption_condition',jsonb_build_object('source_id',v_source_id,'kind',v_kind,
    'required_action','Admit a reviewed retained source and immutable hash for this company. Current retained-source adapter admits only NVDA_SUBMISSIONS with its pinned SHA.','automatic_retry',false,'external_fetch_admitted',false));
 END IF;
 SELECT * INTO v_manifest FROM population_top3000_202608_202609_v1.sec_source_manifest_v1 WHERE source_id='NVDA_SUBMISSIONS' FOR SHARE;
 IF NOT FOUND OR v_manifest.raw_state IS DISTINCT FROM 'COMPLETE_VERIFIED' OR v_manifest.raw_verified_at IS NULL
  OR v_manifest.source_kind IS DISTINCT FROM 'SUBMISSIONS' OR v_manifest.expected_parts IS DISTINCT FROM 2
  OR v_manifest.source_bytes IS DISTINCT FROM 159761::bigint
  OR v_manifest.source_sha256 IS DISTINCT FROM '682c49d59116ae49b317eb4adddf3ef9142dfd97f59c5d8e5a5acad7f9058ab4'
  OR v_manifest.source_uri IS DISTINCT FROM 'https://data.sec.gov/submissions/CIK0001045810.json' THEN
  RETURN jsonb_build_object('state','BLOCKED','blocker_code','RETAINED_COMPANY_MANIFEST_REQUIRED',
   'resumption_condition',jsonb_build_object('retained_source_id','NVDA_SUBMISSIONS','source_id',v_source_id,'required_parts',2,'required_bytes',159761,
    'required_sha256','682c49d59116ae49b317eb4adddf3ef9142dfd97f59c5d8e5a5acad7f9058ab4','required_state','COMPLETE_VERIFIED','automatic_retry',false,'external_fetch_admitted',false));
 END IF;
 PERFORM 1 FROM population_top3000_202608_202609_v1.sec_source_chunk_v1 WHERE source_id='NVDA_SUBMISSIONS' FOR SHARE;
 SELECT count(*),sum(sc.chunk_bytes),min(sc.part_number),max(sc.part_number),string_agg(sc.raw_text,'' ORDER BY sc.part_number),
  count(*) FILTER(WHERE sc.chunk_sha256 IS DISTINCT FROM encode(sha256(convert_to(sc.raw_text,'UTF8')),'hex') OR sc.chunk_bytes IS DISTINCT FROM octet_length(sc.raw_text)::bigint),
  jsonb_agg(jsonb_build_object('part_number',sc.part_number,'chunk_sha256',sc.chunk_sha256,'chunk_bytes',sc.chunk_bytes) ORDER BY sc.part_number)
 INTO v_parts,v_bytes,v_lo,v_hi,v_raw,v_bad,v_chunks
 FROM population_top3000_202608_202609_v1.sec_source_chunk_v1 sc WHERE sc.source_id='NVDA_SUBMISSIONS';
 v_sha:=encode(sha256(convert_to(v_raw,'UTF8')),'hex');
 IF v_parts IS DISTINCT FROM 2::bigint OR v_bytes IS DISTINCT FROM 159761::bigint OR v_lo IS DISTINCT FROM 0 OR v_hi IS DISTINCT FROM 1
  OR v_bad IS DISTINCT FROM 0::bigint OR octet_length(v_raw) IS DISTINCT FROM 159761
  OR v_sha IS DISTINCT FROM v_manifest.source_sha256 THEN
  RETURN jsonb_build_object('state','BLOCKED','blocker_code','RETAINED_COMPANY_SOURCE_INTEGRITY',
   'resumption_condition',jsonb_build_object('retained_source_id','NVDA_SUBMISSIONS','expected_sha256',v_manifest.source_sha256,'observed_sha256',v_sha,
    'expected_parts',2,'observed_parts',v_parts,'expected_bytes',159761,'observed_bytes',v_bytes,'bad_chunk_hashes',v_bad,
    'required_action','Reconcile the immutable retained parts and whole-source hash before importing. Do not overwrite an existing source or fetch automatically.','automatic_retry',false,'external_fetch_admitted',false));
 END IF;
 v_doc:=v_raw::jsonb;
 IF lpad(v_doc->>'cik',10,'0') IS DISTINCT FROM '0001045810' THEN RAISE EXCEPTION 'RETAINED_SUBMISSIONS_CIK_MISMATCH';END IF;
 SELECT * INTO v_existing FROM population_top3000_202608_202609_v1.source_document WHERE source_id=v_source_id FOR UPDATE;
 IF FOUND THEN
  IF v_existing.source_sha256 IS DISTINCT FROM v_sha OR v_existing.content_text IS DISTINCT FROM v_raw
   OR v_existing.content_bytes IS DISTINCT FROM v_bytes OR v_existing.source_uri IS DISTINCT FROM v_manifest.source_uri THEN
   RETURN jsonb_build_object('state','BLOCKED','blocker_code','RETAINED_COMPANY_IMMUTABLE_CONFLICT',
    'resumption_condition',jsonb_build_object('source_id',v_source_id,'expected_sha256',v_sha,'existing_sha256',v_existing.source_sha256,
     'required_action','Reconcile this conflicting source identity; retain existing bytes and do not overwrite.','automatic_retry',false,'external_fetch_admitted',false));
  END IF;
 ELSE
  SELECT * INTO v_control FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;
  IF v_control.stored_bytes+v_control.reserved_bytes+v_bytes>v_control.max_source_bytes THEN
   RETURN jsonb_build_object('state','BLOCKED','blocker_code','RETAINED_COMPANY_STORAGE_LIMIT',
    'resumption_condition',jsonb_build_object('source_id',v_source_id,'additional_copy_bytes',v_bytes,'required_action','Review remaining source-storage admission before materialising this retained source.','automatic_retry',false,'external_fetch_admitted',false));
  END IF;
  INSERT INTO population_top3000_202608_202609_v1.source_document
   (source_id,source_sha256,source_uri,source_provider,retrieved_at,source_published_at,historical_received_at,content_text,content_external_uri,content_bytes,evidence,license_policy)
  VALUES(v_source_id,v_sha,v_manifest.source_uri,'SEC',v_manifest.received_at,NULL,NULL,v_raw,NULL,v_bytes,
   jsonb_build_object('retained_source_id',v_manifest.source_id,'transfer_method','VERIFIED_DATABASE_CHUNKS_NO_NETWORK','chunks',v_chunks,
    'whole_source_verified_sha256',v_sha,'manifest_raw_verified_at',v_manifest.raw_verified_at,'manifest_evidence',v_manifest.evidence,
    'retrieved_at_basis','Retained manifest receipt timestamp; its recorded basis is preserved in manifest_evidence.','imported_at',clock_timestamp(),
    'original_historical_receipt_proven',false,'historical_listing_proven_by_current_tickers',false,'no_provider_request',true),
   'RETAINED_SEC_SOURCE_EVIDENCE_NO_NEW_EXTERNAL_ACCESS');
  GET DIAGNOSTICS v_new_rows=ROW_COUNT;
  UPDATE population_top3000_202608_202609_v1.acquisition_control SET stored_bytes=stored_bytes+v_bytes,updated_at=clock_timestamp() WHERE singleton;
 END IF;
 RETURN jsonb_build_object('state','COMPLETE','commit_receipt',jsonb_build_object(
  'commit_key','company-retained-acquire:'||v_task.operation_key,'output_sha256',v_sha,'new_committed_units',v_new_rows,
  'immutable_output_ids',jsonb_build_array(v_source_id),'input_versions',v_task.input_versions,
  'retained_source_id',v_manifest.source_id,'reused_source_bytes',v_bytes,'additional_copy_bytes',v_new_rows*v_bytes,
  'no_provider_request',true,'original_historical_receipt_proven',false));
END $function$

functions.pipeline_bound_relations_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_bound_relations_v1(p_family text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
declare b population_top3000_202608_202609_v1.pipeline_family_binding%rowtype;e text;o text;
begin
 select * into b from population_top3000_202608_202609_v1.pipeline_family_binding where family_id=p_family;
 if not found then return jsonb_build_object('state','BINDING_MISSING');end if;
 select format('%I.%I',n.nspname,c.relname) into e from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.oid=b.expected_relation and n.nspname='population_top3000_202608_202609_v1' and c.relkind in('r','p','v','m');
 select format('%I.%I',n.nspname,c.relname) into o from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.oid=b.observed_relation and n.nspname='population_top3000_202608_202609_v1' and c.relkind in('r','p','v','m');
 if e is null or o is null then return jsonb_build_object('state','BOUND_RELATION_OUTSIDE_MISSION');end if;
 if population_top3000_202608_202609_v1.pipeline_relation_hash_v1(b.expected_relation) is distinct from b.expected_definition_sha256 or population_top3000_202608_202609_v1.pipeline_relation_hash_v1(b.observed_relation) is distinct from b.observed_definition_sha256 then return jsonb_build_object('state','BOUND_DEFINITION_CHANGED');end if;
 return jsonb_build_object('state','BOUND','expected',e,'observed',o,'binding_version',b.binding_version);
end $function$

functions.sec_import_retained_part_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.sec_import_retained_part_v1(p_owner text, p_fence bigint, p_source_id text, p_source_sha256 text, p_expected_parts integer, p_part_number integer, p_first_source_line integer, p_raw_text text, p_chunk_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare c population_top3000_202608_202609_v1.acquisition_control%rowtype;
s population_top3000_202608_202609_v1.sec_source_manifest_v1%rowtype;
old population_top3000_202608_202609_v1.sec_source_chunk_v1%rowtype;b bigint;n integer;
begin
 select * into c from population_top3000_202608_202609_v1.acquisition_control where singleton for update;
 if not found or c.owner_id is distinct from p_owner or c.owner_fence is distinct from p_fence
  or c.stop_generation<>0 or c.stopped or not c.enabled or c.hold_reason is not null
  or c.admitted_until<=clock_timestamp()
  or c.scope_sha256<>'8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd'
 then raise exception 'SEC_IMPORT_OWNER_STOP_OR_ADMISSION';end if;
 select * into s from population_top3000_202608_202609_v1.sec_source_manifest_v1 where source_id=p_source_id for update;
 if not found or s.source_sha256 is distinct from p_source_sha256 then raise exception 'SEC_IMPORT_SOURCE_VERSION_MISMATCH';end if;
 b:=octet_length(p_raw_text);
 if p_expected_parts is null or p_expected_parts not between 1 and 1000
  or p_part_number is null or p_part_number not between 0 and p_expected_parts-1
  or b is null or b not between 1 and 524288
  or p_chunk_sha256 is distinct from encode(sha256(convert_to(p_raw_text,'UTF8')),'hex')
  or (s.source_kind='QUARTER_INDEX' and (p_first_source_line is null or p_first_source_line<1))
 then raise exception 'SEC_IMPORT_PART_INVALID';end if;
 if s.expected_parts is not null and s.expected_parts<>p_expected_parts then raise exception 'SEC_IMPORT_LAYOUT_CONFLICT';end if;
 select * into old from population_top3000_202608_202609_v1.sec_source_chunk_v1 where source_id=p_source_id and part_number=p_part_number;
 if found then
  if old.chunk_sha256<>p_chunk_sha256 or old.raw_text<>p_raw_text or old.first_source_line is distinct from p_first_source_line then raise exception 'SEC_IMPORT_IMMUTABLE_CONFLICT';end if;
  return jsonb_build_object('state','REUSED','source_id',p_source_id,'part',p_part_number,'new_bytes',0);
 end if;
 if c.stored_bytes+c.reserved_bytes+b>c.max_source_bytes then raise exception 'SEC_IMPORT_STORAGE_CAP';end if;
 insert into population_top3000_202608_202609_v1.sec_source_chunk_v1(source_id,part_number,first_source_line,raw_text,chunk_sha256,chunk_bytes)
 values(p_source_id,p_part_number,p_first_source_line,p_raw_text,p_chunk_sha256,b);
 update population_top3000_202608_202609_v1.sec_source_manifest_v1 set expected_parts=p_expected_parts,raw_state='PARTIAL',
 evidence=evidence||jsonb_build_object('transfer_method','RETAINED_LOCAL_SOURCE_NO_REDOWLOAD','original_historical_receipt_proven',false)
 where source_id=p_source_id;
 update population_top3000_202608_202609_v1.acquisition_control set stored_bytes=stored_bytes+b,last_useful_progress_at=clock_timestamp(),updated_at=clock_timestamp() where singleton;
 insert into population_top3000_202608_202609_v1.acquisition_event(event,details)
 values('RETAINED_SEC_PART_COMMITTED',jsonb_build_object('source_id',p_source_id,'part_number',p_part_number,'sha256',p_chunk_sha256,'new_bytes',b,'owner_fence',p_fence));
 return jsonb_build_object('state','COMMITTED','source_id',p_source_id,'part',p_part_number,'new_bytes',b);
end $function$

functions.pipeline_provider_release_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_provider_release_v1(p_attempt uuid, p_token text, p_received_bytes bigint, p_actual_usd numeric, p_retry_after_seconds integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;l population_top3000_202608_202609_v1.pipeline_provider_lease%rowtype;
begin
tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
select * into l from population_top3000_202608_202609_v1.pipeline_provider_lease where attempt_id=p_attempt for update;
if not found then raise exception 'RESERVATION_MISSING';end if;
if l.released_at is not null then return '{"state":"ALREADY_RELEASED"}';end if;
if p_received_bytes is null or p_received_bytes<0 or p_received_bytes>l.reserved_bytes or p_actual_usd is null or p_actual_usd<0 or p_actual_usd>l.reserved_usd or p_retry_after_seconds is null or p_retry_after_seconds<0 then raise exception 'ACTUAL_EXCEEDS_ENFORCEABLE_RESERVATION';end if;
update population_top3000_202608_202609_v1.acquisition_control set reserved_bytes=reserved_bytes-l.reserved_bytes,stored_bytes=stored_bytes+p_received_bytes,next_provider_at=greatest(next_provider_at,clock_timestamp()+make_interval(secs=>p_retry_after_seconds)) where singleton;
update population_top3000_202608_202609_v1.pipeline_control set reserved_request_usd=reserved_request_usd-l.reserved_usd,accrued_usd=accrued_usd+p_actual_usd where singleton;
update population_top3000_202608_202609_v1.pipeline_provider_lease set released_at=clock_timestamp(),received_bytes=p_received_bytes,actual_usd=p_actual_usd,outcome=case when p_retry_after_seconds>0 then 'PROVIDER_WAIT' else 'RECEIVED' end where attempt_id=p_attempt;
return '{"state":"RELEASED"}';
end $function$

functions.pipeline_provider_reserve_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.pipeline_provider_reserve_v1(p_attempt uuid, p_token text, p_provider text, p_max_bytes bigint, p_max_incremental_usd numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
declare tid uuid;c population_top3000_202608_202609_v1.acquisition_control%rowtype;p population_top3000_202608_202609_v1.pipeline_control%rowtype;
begin
tid:=population_top3000_202608_202609_v1.pipeline_assert_attempt_v1(p_attempt,p_token);
if p_provider is null or p_max_bytes is null or p_max_bytes<=0 or p_max_bytes>33554432 or p_max_incremental_usd is null or p_max_incremental_usd<0 then raise exception 'RESERVATION_INVALID';end if;
select * into c from population_top3000_202608_202609_v1.acquisition_control where singleton;
select * into p from population_top3000_202608_202609_v1.pipeline_control where singleton;
if exists(select 1 from population_top3000_202608_202609_v1.pipeline_provider_lease where attempt_id=p_attempt) then raise exception 'REQUEST_ALREADY_RESERVED_FOR_ATTEMPT';end if;
if c.next_provider_at>clock_timestamp() then return jsonb_build_object('state','WAIT','not_before',c.next_provider_at);end if;
if exists(select 1 from population_top3000_202608_202609_v1.pipeline_provider_lease where released_at is null)
 or exists(select 1 from population_top3000_202608_202609_v1.acquisition_job where status='LEASED' and lease_until>clock_timestamp()) then return jsonb_build_object('state','WAIT','not_before',clock_timestamp()+interval '5 seconds');end if;
if p.budget_verified_at is null or p.budget_evidence is null or coalesce((p.budget_evidence->>'provider_admissions_allowed')::boolean,false) is not true then return '{"state":"BUDGET_HOLD","reason":"CURRENT_MISSION_BILLING_BASELINE_REQUIRED"}';end if;
if (coalesce(p.budget_evidence->'allowed_providers','[]'::jsonb) ? p_provider) is not true then
 return jsonb_build_object('state','BUDGET_HOLD','reason','PROVIDER_NOT_IN_CURRENT_ADMISSION');
end if;
if p_max_bytes>8388608 then return jsonb_build_object('state','BUDGET_HOLD','reason','PER_RESPONSE_BYTE_LIMIT');end if;
if nullif(p.budget_evidence#>>'{resource_limits,max_relation_bytes}','') is null
 or (select coalesce(sum(pg_total_relation_size(r.oid)),0) from pg_class r join pg_namespace n on n.oid=r.relnamespace
 where n.nspname='population_top3000_202608_202609_v1' and r.relkind in('r','m')) >= (p.budget_evidence#>>'{resource_limits,max_relation_bytes}')::bigint
then return jsonb_build_object('state','BUDGET_HOLD','reason','MISSION_RELATION_STORAGE_BOUND');end if;
if c.provider_requests>=c.max_provider_requests or c.stored_bytes+c.reserved_bytes+p_max_bytes>c.max_source_bytes or p.actual_usd+p.accrued_usd+p.unavoidable_usd+p.remaining_uncommitted_usd+p.repair_egress_reserve_usd+p.reserved_request_usd+p_max_incremental_usd>250 then return '{"state":"BUDGET_HOLD","reason":"CONSERVATIVE_TOTAL_OR_RESOURCE_LIMIT"}';end if;
insert into population_top3000_202608_202609_v1.pipeline_provider_lease(attempt_id,provider,reserved_bytes,reserved_usd)values(p_attempt,p_provider,p_max_bytes,p_max_incremental_usd);
update population_top3000_202608_202609_v1.acquisition_control set provider_requests=provider_requests+1,reserved_bytes=reserved_bytes+p_max_bytes,next_provider_at=clock_timestamp()+interval '500 milliseconds' where singleton;
update population_top3000_202608_202609_v1.pipeline_control set reserved_request_usd=reserved_request_usd+p_max_incremental_usd where singleton;
return jsonb_build_object('state','RESERVED','max_bytes',p_max_bytes,'max_incremental_usd',p_max_incremental_usd);
end $function$

functions.sec_verify_retained_source_v1:
CREATE OR REPLACE FUNCTION population_top3000_202608_202609_v1.sec_verify_retained_source_v1(p_owner text, p_fence bigint, p_source_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
declare c population_top3000_202608_202609_v1.acquisition_control%rowtype;s population_top3000_202608_202609_v1.sec_source_manifest_v1%rowtype;
n integer;b bigint;lo integer;hi integer;h text;bad integer;
begin
 select * into c from population_top3000_202608_202609_v1.acquisition_control where singleton for update;
 if c.owner_id is distinct from p_owner or c.owner_fence is distinct from p_fence or c.stop_generation<>0 or c.stopped or not c.enabled or c.hold_reason is not null or c.admitted_until<=clock_timestamp() then raise exception 'SEC_IMPORT_OWNER_STOP_OR_ADMISSION';end if;
 select * into s from population_top3000_202608_202609_v1.sec_source_manifest_v1 where source_id=p_source_id for update;
 if not found then raise exception 'SEC_SOURCE_UNKNOWN';end if;
 select count(*),sum(chunk_bytes),min(part_number),max(part_number),encode(sha256(convert_to(string_agg(raw_text,'' order by part_number),'UTF8')),'hex'),
 count(*) filter(where chunk_sha256<>encode(sha256(convert_to(raw_text,'UTF8')),'hex') or chunk_bytes<>octet_length(raw_text))
 into n,b,lo,hi,h,bad from population_top3000_202608_202609_v1.sec_source_chunk_v1 where source_id=p_source_id;
 if n is distinct from s.expected_parts or b is distinct from s.source_bytes or lo<>0 or hi<>n-1 or h is distinct from s.source_sha256 or bad<>0 then raise exception 'SEC_RAW_HASH_OR_PART_RECONCILIATION_FAILED';end if;
 update population_top3000_202608_202609_v1.sec_source_manifest_v1 set raw_state='COMPLETE_VERIFIED',raw_verified_at=coalesce(raw_verified_at,clock_timestamp()) where source_id=p_source_id;
 return jsonb_build_object('state','COMPLETE_VERIFIED','source_id',p_source_id,'parts',n,'bytes',b,'source_sha256',h,'bad_part_hashes',bad,'original_historical_receipt_proven',false);
end $function$
